import { useState, useEffect } from 'react';
import { HiOutlineSun, HiOutlineMoon } from 'react-icons/hi';

export default function ThemeToggle() {
  const [theme, setTheme] = useState('light');

  useEffect(() => {
    // Read theme from DOM (in case index.html script ran first) or localStorage
    const currentTheme = document.documentElement.getAttribute('data-theme') || 
                         localStorage.getItem('sts-theme') || 
                         'light';
    setTheme(currentTheme);
    document.documentElement.setAttribute('data-theme', currentTheme);
  }, []);

  const toggleTheme = () => {
    const nextTheme = theme === 'light' ? 'dark' : 'light';
    setTheme(nextTheme);
    document.documentElement.setAttribute('data-theme', nextTheme);
    localStorage.setItem('sts-theme', nextTheme);
  };

  return (
    <button 
      className="theme-toggle-switch" 
      onClick={toggleTheme}
      title={`Switch to ${theme === 'light' ? 'dark' : 'light'} theme`}
      aria-label="Toggle theme"
    >
      <div className="theme-toggle-track">
        <HiOutlineSun className="track-icon-sun" />
        <HiOutlineMoon className="track-icon-moon" />
      </div>
      <div className="theme-toggle-thumb">
        {theme === 'light' ? (
          <HiOutlineSun key="sun" />
        ) : (
          <HiOutlineMoon key="moon" />
        )}
      </div>
    </button>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import client from '../../api/client';
import ConfirmDialog from '../../components/ConfirmDialog';
import {
  HiOutlineBriefcase, HiOutlineSearch, HiOutlineAcademicCap,
  HiOutlineDocumentDownload, HiOutlineEye, HiOutlineArrowLeft,
  HiOutlineOfficeBuilding, HiOutlineCollection, HiOutlineCalendar
} from 'react-icons/hi';

export default function AlumniDatabase() {
  const [alumni, setAlumni] = useState([]);
  const [stats, setStats] = useState(null);
  const [departments, setDepartments] = useState([]);
  const [batches, setBatches] = useState([]);
  const [loading, setLoading] = useState(true);
  const [revertTarget, setRevertTarget] = useState(null);
  const [reverting, setReverting] = useState(false);

  // Filter States
  const [search, setSearch] = useState('');
  const [selectedDept, setSelectedDept] = useState('');
  const [selectedBatch, setSelectedBatch] = useState('');
  const [selectedYear, setSelectedYear] = useState('');
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalCount, setTotalCount] = useState(0);

  // Detail Modal State
  const [previewAlumni, setPreviewAlumni] = useState(null);
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [editForm, setEditForm] = useState({
    graduationDate: '',
    graduationYear: '',
    currentEmployer: '',
    currentJobTitle: '',
    linkedInUrl: '',
    alumniEmail: '',
    notes: '',
  });

  const navigate = useNavigate();

  const fetchData = async () => {
    try {
      const params = {
        search,
        departmentId: selectedDept,
        batchId: selectedBatch,
        graduationYear: selectedYear,
        page,
        limit: 15,
      };

      const [alumniRes, statsRes, deptRes, batchRes] = await Promise.all([
        client.get('/admin/alumni', { params }),
        client.get('/admin/alumni/stats'),
        client.get('/admin/departments'),
        client.get('/admin/batches')
      ]);

      setAlumni(alumniRes.data.alumni);
      setTotalPages(alumniRes.data.totalPages);
      setTotalCount(alumniRes.data.total);

      setStats(statsRes.data.stats);
      setDepartments(deptRes.data.departments);
      setBatches(batchRes.data.batches);
    } catch (err) {
      console.error('Failed to fetch alumni data:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [search, selectedDept, selectedBatch, selectedYear, page]);

  const handleRevert = async () => {
    if (!revertTarget) return;
    setReverting(true);
    try {
      await client.post(`/admin/alumni/${revertTarget}/revert`);
      setRevertTarget(null);
      if (previewAlumni?.id === revertTarget) {
        setPreviewAlumni(null);
      }
      fetchData();
      alert('Alumni status reverted back to active student successfully');
    } catch (err) {
      console.error(err);
      alert(err.response?.data?.error || 'Failed to revert alumni status');
    } finally {
      setReverting(false);
    }
  };

  const handleOpenPreview = (student) => {
    setPreviewAlumni(student);
    setEditing(false);
    const profile = student.alumniProfile || {};
    setEditForm({
      graduationDate: profile.graduationDate ? new Date(profile.graduationDate).toISOString().split('T')[0] : new Date().toISOString().split('T')[0],
      graduationYear: profile.graduationYear || new Date().getFullYear(),
      currentEmployer: profile.currentEmployer || '',
      currentJobTitle: profile.currentJobTitle || '',
      linkedInUrl: profile.linkedInUrl || '',
      alumniEmail: profile.alumniEmail || '',
      notes: profile.notes || '',
    });
  };

  const handleUpdateProfile = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      await client.put(`/admin/alumni/${previewAlumni.id}`, editForm);
      setEditing(false);
      // Fetch fresh details and refresh preview
      const { data } = await client.get(`/admin/alumni`, {
        params: { search: previewAlumni.enrollmentNo }
      });
      if (data.alumni && data.alumni.length > 0) {
        setPreviewAlumni(data.alumni[0]);
      }
      fetchData();
      alert('Alumni profile updated successfully!');
    } catch (err) {
      console.error(err);
      alert(err.response?.data?.error || 'Failed to update profile');
    } finally {
      setSaving(false);
    }
  };

  const handleExportCSV = () => {
    if (alumni.length === 0) {
      alert('No alumni records available to export');
      return;
    }

    const headers = [
      'Enrollment No', 'First Name', 'Last Name', 'Email', 'Phone',
      'Degree', 'Batch', 'Department', 'Semester', 'Status',
      'Graduation Date', 'Graduation Year', 'Current Employer', 'Current Job Title',
      'Alumni Email', 'LinkedIn URL', 'Notes'
    ];

    const rows = alumni.map(a => {
      const p = a.alumniProfile || {};
      return [
        a.enrollmentNo,
        a.firstName,
        a.lastName,
        a.user?.email || '',
        a.phone,
        a.batch?.degree || '',
        a.batch?.name || '',
        a.batch?.department?.name || '',
        a.semester,
        a.status,
        p.graduationDate ? new Date(p.graduationDate).toLocaleDateString() : '',
        p.graduationYear || '',
        p.currentEmployer || '',
        p.currentJobTitle || '',
        p.alumniEmail || '',
        p.linkedInUrl || '',
        p.notes || ''
      ];
    });

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.map(val => `"${String(val).replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `Alumni_Export_${new Date().getFullYear()}-${new Date().getMonth()+1}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (loading && page === 1 && alumni.length === 0) {
    return <div className="loading-container"><div className="spinner spinner-lg" /></div>;
  }

  // Calculate employment rate
  const total = stats?.totalAlumni || 0;
  const employed = stats?.employment?.employed || 0;
  const rate = total > 0 ? Math.round((employed / total) * 100) : 0;

  // Generate graduation years list for filter
  const currentYear = new Date().getFullYear();
  const graduationYears = [];
  for (let y = currentYear; y >= currentYear - 6; y--) {
    graduationYears.push(y);
  }

  return (
    <div>
      {/* Header */}
      <div className="page-header">
        <div>
          <h1>Alumni Database</h1>
          <p className="page-subtitle">Track and manage graduated student profiles</p>
        </div>
        <button className="btn btn-secondary btn-sm" onClick={handleExportCSV}>
          <HiOutlineDocumentDownload /> Export CSV
        </button>
      </div>

      {/* Stats Section */}
      <div className="stats-grid" style={{ marginBottom: 'var(--space-6)' }}>
        <div className="stat-card slide-up">
          <div className="stat-icon purple">
            <HiOutlineAcademicCap />
          </div>
          <div className="stat-info">
            <div className="stat-value">{stats?.totalAlumni || 0}</div>
            <div className="stat-label">Total Alumni</div>
          </div>
        </div>

        <div className="stat-card slide-up" style={{ animationDelay: '50ms' }}>
          <div className="stat-icon green">
            <HiOutlineBriefcase />
          </div>
          <div className="stat-info">
            <div className="stat-value">{stats?.employment?.employed || 0}</div>
            <div className="stat-label">Employed</div>
          </div>
        </div>

        <div className="stat-card slide-up" style={{ animationDelay: '100ms' }}>
          <div className="stat-icon amber">
            <HiOutlineBriefcase />
          </div>
          <div className="stat-info">
            <div className="stat-value">{stats?.employment?.unemployed || 0}</div>
            <div className="stat-label">Higher Ed / Seeking / Unspecified</div>
          </div>
        </div>

        <div className="stat-card slide-up" style={{ animationDelay: '150ms' }}>
          <div className="stat-icon sky">
            <HiOutlineBriefcase />
          </div>
          <div className="stat-info">
            <div className="stat-value">{rate}%</div>
            <div className="stat-label">Employment Rate</div>
          </div>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="card" style={{ marginBottom: 'var(--space-6)' }}>
        <div className="card-body" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 'var(--space-4)' }}>

            {/* Search */}
            <div className="form-group">
              <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
                <HiOutlineSearch style={{ fontSize: '0.9rem' }} /> Search
              </label>
              <input
                className="form-input"
                placeholder="Search name, enrollment, company..."
                value={search}
                onChange={(e) => { setSearch(e.target.value); setPage(1); }}
              />
            </div>

            {/* Department */}
            <div className="form-group">
              <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
                <HiOutlineOfficeBuilding style={{ fontSize: '0.9rem' }} /> Department
              </label>
              <select
                className="form-select"
                value={selectedDept}
                onChange={(e) => { setSelectedDept(e.target.value); setSelectedBatch(''); setPage(1); }}
              >
                <option value="">All Departments</option>
                {departments.map(d => (
                  <option key={d.id} value={d.id}>{d.name}</option>
                ))}
              </select>
            </div>

            {/* Batch */}
            <div className="form-group">
              <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
                <HiOutlineCollection style={{ fontSize: '0.9rem' }} /> Batch
              </label>
              <select
                className="form-select"
                value={selectedBatch}
                onChange={(e) => { setSelectedBatch(e.target.value); setPage(1); }}
              >
                <option value="">All Batches</option>
                {batches
                  .filter(b => !selectedDept || b.departmentId === selectedDept)
                  .map(b => (
                    <option key={b.id} value={b.id}>{b.degree} — {b.name}</option>
                  ))}
              </select>
            </div>

            {/* Graduation Year */}
            <div className="form-group">
              <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
                <HiOutlineCalendar style={{ fontSize: '0.9rem' }} /> Graduation Year
              </label>
              <select
                className="form-select"
                value={selectedYear}
                onChange={(e) => { setSelectedYear(e.target.value); setPage(1); }}
              >
                <option value="">All Years</option>
                {graduationYears.map(y => (
                  <option key={y} value={y}>{y}</option>
                ))}
              </select>
            </div>

          </div>
        </div>
      </div>

      {/* Main Datatable */}
      <div className="card">
        <div className="data-table-wrapper">
          <table className="data-table">
            <thead>
              <tr>
                <th>Student</th>
                <th>Department & Batch</th>
                <th>Graduation</th>
                <th>Current Employer</th>
                <th>Job Title</th>
                <th>LinkedIn</th>
                <th style={{ textAlign: 'right' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {alumni.length === 0 ? (
                <tr>
                  <td colSpan="7">
                    <div className="empty-state">
                      <p>No alumni profiles found matching the filters.</p>
                    </div>
                  </td>
                </tr>
              ) : (
                alumni.map((alum) => {
                  const prof = alum.alumniProfile || {};
                  return (
                    <tr key={alum.id}>
                      <td>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
                          <div className="user-avatar" style={{ width: '40px', height: '40px', fontSize: '1rem', fontWeight: 600 }}>
                            {alum.firstName.charAt(0)}{alum.lastName.charAt(0)}
                          </div>
                          <div>
                            <div style={{ fontWeight: 600, color: 'var(--color-gray-800)' }}>
                              {alum.firstName} {alum.lastName}
                            </div>
                            <div style={{ fontSize: 'var(--font-xs)', color: 'var(--color-gray-400)' }}>
                              {alum.enrollmentNo}
                            </div>
                          </div>
                        </div>
                      </td>
                      <td>
                        <div style={{ fontWeight: 500 }}>{alum.batch?.department?.name || '—'}</div>
                        <div style={{ fontSize: 'var(--font-sm)', color: 'var(--color-gray-500)' }}>
                          {alum.batch?.degree} {alum.batch?.name}
                        </div>
                      </td>
                      <td>
                        <div style={{ fontWeight: 600, color: 'var(--color-purple)' }}>
                          Class of {prof.graduationYear || '—'}
                        </div>
                        <div style={{ fontSize: 'var(--font-xs)', color: 'var(--color-gray-400)' }}>
                          {prof.graduationDate ? new Date(prof.graduationDate).toLocaleDateString() : '—'}
                        </div>
                      </td>
                      <td style={{ fontWeight: 500 }}>{prof.currentEmployer || '—'}</td>
                      <td>{prof.currentJobTitle || '—'}</td>
                      <td>
                        {prof.linkedInUrl ? (
                          <a
                            href={prof.linkedInUrl}
                            target="_blank"
                            rel="noreferrer"
                            className="badge badge-sky"
                            style={{ cursor: 'pointer', textDecoration: 'none' }}
                          >
                            LinkedIn
                          </a>
                        ) : '—'}
                      </td>
                      <td className="actions" style={{ textAlign: 'right' }}>
                        <button
                          className="btn btn-ghost btn-sm"
                          onClick={() => handleOpenPreview(alum)}
                          title="View Profile"
                        >
                          <HiOutlineEye />
                        </button>
                        <button
                          className="btn btn-ghost btn-sm"
                          style={{ color: 'var(--color-danger)' }}
                          onClick={() => setRevertTarget(alum.id)}
                          title="Revert to Active Student"
                        >
                          <HiOutlineArrowLeft />
                        </button>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: 'var(--space-4) var(--space-6)', borderTop: '1px solid var(--color-gray-100)' }}>
            <span style={{ fontSize: 'var(--font-sm)', color: 'var(--color-gray-500)' }}>
              Showing {alumni.length} of {totalCount} alumni
            </span>
            <div style={{ display: 'flex', gap: 'var(--space-2)' }}>
              <button
                className="btn btn-secondary btn-sm"
                disabled={page === 1}
                onClick={() => setPage(page - 1)}
              >
                Previous
              </button>
              <button
                className="btn btn-secondary btn-sm"
                disabled={page === totalPages}
                onClick={() => setPage(page + 1)}
              >
                Next
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Alumni Detail Modal */}
      {previewAlumni && (
        <div className="modal-overlay" onClick={() => setPreviewAlumni(null)} style={{ backdropFilter: 'blur(4px)' }}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()} style={{ maxWidth: '650px' }}>
            <div className="modal-header">
              <h2>Alumni Details</h2>
              <button className="btn btn-ghost" onClick={() => setPreviewAlumni(null)}>✕</button>
            </div>

            <div className="modal-body" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>

              {/* Header profile cards */}
              <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-4)', paddingBottom: 'var(--space-4)', borderBottom: '1px solid var(--color-gray-100)' }}>
                <div className="user-avatar" style={{ width: '60px', height: '60px', fontSize: '1.4rem', fontWeight: 600 }}>
                  {previewAlumni.firstName.charAt(0)}{previewAlumni.lastName.charAt(0)}
                </div>
                <div>
                  <h3 style={{ fontSize: 'var(--font-xl)', fontWeight: 700, margin: 0 }}>
                    {previewAlumni.firstName} {previewAlumni.lastName}
                  </h3>
                  <div style={{ display: 'flex', gap: 'var(--space-2)', marginTop: 'var(--space-1)', flexWrap: 'wrap' }}>
                    <span className="badge badge-sky">{previewAlumni.enrollmentNo}</span>
                    <span className="badge badge-purple">Class of {previewAlumni.alumniProfile?.graduationYear}</span>
                    <span className="badge badge-gray">{previewAlumni.batch?.department?.name}</span>
                  </div>
                </div>
              </div>

              {editing ? (
                <form onSubmit={handleUpdateProfile}>
                  <div className="form-row">
                    <div className="form-group">
                      <label className="form-label">Graduation Date *</label>
                      <input
                        type="date"
                        className="form-input"
                        value={editForm.graduationDate}
                        onChange={(e) => setEditForm({ ...editForm, graduationDate: e.target.value })}
                        required
                      />
                    </div>
                    <div className="form-group">
                      <label className="form-label">Graduation Year *</label>
                      <input
                        type="number"
                        className="form-input"
                        value={editForm.graduationYear}
                        onChange={(e) => setEditForm({ ...editForm, graduationYear: parseInt(e.target.value) })}
                        required
                      />
                    </div>
                  </div>

                  <div className="form-row" style={{ marginTop: 'var(--space-3)' }}>
                    <div className="form-group">
                      <label className="form-label">Current Employer</label>
                      <input
                        className="form-input"
                        value={editForm.currentEmployer}
                        onChange={(e) => setEditForm({ ...editForm, currentEmployer: e.target.value })}
                        placeholder="e.g. Google"
                      />
                    </div>
                    <div className="form-group">
                      <label className="form-label">Current Job Title</label>
                      <input
                        className="form-input"
                        value={editForm.currentJobTitle}
                        onChange={(e) => setEditForm({ ...editForm, currentJobTitle: e.target.value })}
                        placeholder="e.g. Software Engineer"
                      />
                    </div>
                  </div>

                  <div className="form-row" style={{ marginTop: 'var(--space-3)' }}>
                    <div className="form-group">
                      <label className="form-label">Alumni Email</label>
                      <input
                        type="email"
                        className="form-input"
                        value={editForm.alumniEmail}
                        onChange={(e) => setEditForm({ ...editForm, alumniEmail: e.target.value })}
                        placeholder="e.g. name@alumni.com"
                      />
                    </div>
                    <div className="form-group">
                      <label className="form-label">LinkedIn Profile URL</label>
                      <input
                        type="url"
                        className="form-input"
                        value={editForm.linkedInUrl}
                        onChange={(e) => setEditForm({ ...editForm, linkedInUrl: e.target.value })}
                        placeholder="e.g. https://linkedin.com/in/username"
                      />
                    </div>
                  </div>

                  <div className="form-group" style={{ marginTop: 'var(--space-3)' }}>
                    <label className="form-label">Notes</label>
                    <textarea
                      className="form-input"
                      value={editForm.notes}
                      onChange={(e) => setEditForm({ ...editForm, notes: e.target.value })}
                      placeholder="Notes on post-graduation pursuits..."
                      rows={2}
                    />
                  </div>

                  <div style={{ display: 'flex', gap: 'var(--space-3)', marginTop: 'var(--space-5)', justifyContent: 'flex-end' }}>
                    <button type="button" className="btn btn-secondary" onClick={() => setEditing(false)}>
                      Cancel
                    </button>
                    <button type="submit" className="btn btn-primary" disabled={saving}>
                      {saving ? 'Saving...' : 'Save Changes'}
                    </button>
                  </div>
                </form>
              ) : (
                <div>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 'var(--space-4)', marginBottom: 'var(--space-5)' }}>
                    <div>
                      <h4 style={{ fontSize: 'var(--font-xs)', fontWeight: 600, color: 'var(--color-gray-400)', textTransform: 'uppercase', marginBottom: 'var(--space-1)' }}>
                        Current Employer
                      </h4>
                      <div style={{ fontWeight: 600, color: 'var(--color-gray-800)' }}>
                        {previewAlumni.alumniProfile?.currentEmployer || '—'}
                      </div>
                    </div>
                    <div>
                      <h4 style={{ fontSize: 'var(--font-xs)', fontWeight: 600, color: 'var(--color-gray-400)', textTransform: 'uppercase', marginBottom: 'var(--space-1)' }}>
                        Current Job Title
                      </h4>
                      <div style={{ fontWeight: 600, color: 'var(--color-gray-800)' }}>
                        {previewAlumni.alumniProfile?.currentJobTitle || '—'}
                      </div>
                    </div>
                    <div>
                      <h4 style={{ fontSize: 'var(--font-xs)', fontWeight: 600, color: 'var(--color-gray-400)', textTransform: 'uppercase', marginBottom: 'var(--space-1)' }}>
                        Graduation Date
                      </h4>
                      <div>
                        {previewAlumni.alumniProfile?.graduationDate ? new Date(previewAlumni.alumniProfile.graduationDate).toLocaleDateString() : '—'}
                      </div>
                    </div>
                    <div>
                      <h4 style={{ fontSize: 'var(--font-xs)', fontWeight: 600, color: 'var(--color-gray-400)', textTransform: 'uppercase', marginBottom: 'var(--space-1)' }}>
                        Alumni Email
                      </h4>
                      <div>{previewAlumni.alumniProfile?.alumniEmail || '—'}</div>
                    </div>
                    <div>
                      <h4 style={{ fontSize: 'var(--font-xs)', fontWeight: 600, color: 'var(--color-gray-400)', textTransform: 'uppercase', marginBottom: 'var(--space-1)' }}>
                        LinkedIn Profile
                      </h4>
                      <div>
                        {previewAlumni.alumniProfile?.linkedInUrl ? (
                          <a href={previewAlumni.alumniProfile.linkedInUrl} target="_blank" rel="noreferrer" style={{ color: 'var(--color-primary)', fontWeight: 600 }}>
                            View LinkedIn profile
                          </a>
                        ) : '—'}
                      </div>
                    </div>
                    <div>
                      <h4 style={{ fontSize: 'var(--font-xs)', fontWeight: 600, color: 'var(--color-gray-400)', textTransform: 'uppercase', marginBottom: 'var(--space-1)' }}>
                        Student Phone
                      </h4>
                      <div>{previewAlumni.phone}</div>
                    </div>
                  </div>

                  {previewAlumni.alumniProfile?.notes && (
                    <div style={{ padding: 'var(--space-3) var(--space-4)', background: 'var(--color-gray-50)', borderRadius: 'var(--radius-md)', marginBottom: 'var(--space-5)' }}>
                      <h4 style={{ fontSize: 'var(--font-xs)', fontWeight: 600, color: 'var(--color-gray-400)', textTransform: 'uppercase', marginBottom: 'var(--space-1)' }}>
                        Notes
                      </h4>
                      <p style={{ margin: 0, fontSize: 'var(--font-sm)', color: 'var(--color-gray-600)' }}>
                        {previewAlumni.alumniProfile.notes}
                      </p>
                    </div>
                  )}

                  <div style={{ display: 'flex', gap: 'var(--space-3)', justifyContent: 'flex-end', borderTop: '1px solid var(--color-gray-100)', paddingTop: 'var(--space-4)' }}>
                    <button
                      type="button"
                      className="btn btn-ghost"
                      style={{ color: 'var(--color-danger)' }}
                      onClick={() => setRevertTarget(previewAlumni.id)}
                    >
                      Revert to Active Student
                    </button>
                    <button
                      type="button"
                      className="btn btn-secondary"
                      onClick={() => navigate(`/admin/students/${previewAlumni.id}`)}
                    >
                      View Academic Record
                    </button>
                    <button
                      type="button"
                      className="btn btn-primary"
                      onClick={() => setEditing(true)}
                    >
                      Edit Profile
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Revert Confirm Dialog */}
      <ConfirmDialog
        open={!!revertTarget}
        title="Revert Alumni Status?"
        message="This will change the student status back to 'active' and permanently delete their post-graduation profile data. Are you sure you want to proceed?"
        onConfirm={handleRevert}
        onCancel={() => setRevertTarget(null)}
        loading={reverting}
      />
    </div>
  );
}

import { useState, useEffect } from 'react';
import client from '../../api/client';
import ConfirmDialog from '../../components/ConfirmDialog';
import { HiOutlinePlus, HiOutlinePencil, HiOutlineTrash } from 'react-icons/hi';

export default function ManageBatches() {
  const [batches, setBatches] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({ name: '', departmentId: '', degree: '', startYear: '', endYear: '' });
  const [saving, setSaving] = useState(false);
  const [filterDept, setFilterDept] = useState('');
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [deleting, setDeleting] = useState(false);

  const fetchData = async () => {
    try {
      const [batchRes, deptRes] = await Promise.all([
        client.get('/admin/batches', { params: filterDept ? { departmentId: filterDept } : {} }),
        client.get('/admin/departments'),
      ]);
      setBatches(batchRes.data.batches);
      setDepartments(deptRes.data.departments);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  };

  useEffect(() => { fetchData(); }, [filterDept]);

  const openCreate = () => {
    setEditing(null);
    setForm({ name: '', departmentId: departments[0]?.id || '', degree: '', startYear: new Date().getFullYear().toString(), endYear: (new Date().getFullYear() + 4).toString() });
    setShowModal(true);
  };
  const openEdit = (b) => {
    setEditing(b);
    setForm({ name: b.name, departmentId: b.departmentId, degree: b.degree, startYear: b.startYear.toString(), endYear: b.endYear.toString() });
    setShowModal(true);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editing) await client.put(`/admin/batches/${editing.id}`, form);
      else await client.post('/admin/batches', form);
      setShowModal(false);
      fetchData();
    } catch (err) { alert(err.response?.data?.error || 'Error'); }
    finally { setSaving(false); }
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    setDeleting(true);
    try {
      await client.delete(`/admin/batches/${deleteTarget}`);
      setDeleteTarget(null);
      fetchData();
    } catch (err) {
      alert(err.response?.data?.error || 'Failed to delete batch');
    } finally {
      setDeleting(false);
    }
  };

  if (loading) return <div className="loading-container"><div className="spinner spinner-lg" /></div>;

  return (
    <div>
      <div className="page-header">
        <div>
          <h1>Batches</h1>
          <p className="page-subtitle">Manage student batches</p>
        </div>
        <button className="btn btn-primary" onClick={openCreate}><HiOutlinePlus /> Add Batch</button>
      </div>

      <div className="toolbar">
        <div className="filter-group">
          <select className="form-select" value={filterDept} onChange={(e) => setFilterDept(e.target.value)} style={{ width: 'auto' }}>
            <option value="">All Departments</option>
            {departments.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
          </select>
        </div>
      </div>

      <div className="card">
        <div className="data-table-wrapper">
          <table className="data-table">
            <thead><tr><th>Name</th><th>Department</th><th>Degree</th><th>Year</th><th>Sections</th><th>Students</th><th>Actions</th></tr></thead>
            <tbody>
              {batches.length === 0 ? (
                <tr><td colSpan="7"><div className="empty-state"><p>No batches yet.</p></div></td></tr>
              ) : batches.map((b) => (
                <tr key={b.id}>
                  <td style={{ fontWeight: 500 }}>{b.name}</td>
                  <td><span className="badge badge-purple">{b.department?.name}</span></td>
                  <td>{b.degree}</td>
                  <td>{b.startYear}–{b.endYear}</td>
                  <td>{b._count?.sections || 0}</td>
                  <td>{b._count?.students || 0}</td>
                  <td className="actions">
                    <button className="btn btn-ghost btn-sm" onClick={() => openEdit(b)}><HiOutlinePencil /></button>
                    <button className="btn btn-ghost btn-sm" onClick={() => setDeleteTarget(b.id)} title="Delete" style={{ color: 'var(--color-danger)' }}><HiOutlineTrash /></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {showModal && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>{editing ? 'Edit Batch' : 'Add Batch'}</h2>
              <button className="btn btn-ghost" onClick={() => setShowModal(false)}>✕</button>
            </div>
            <form onSubmit={handleSubmit}>
              <div className="modal-body" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
                <div className="form-group">
                  <label className="form-label">Batch Name</label>
                  <input className="form-input" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required placeholder="e.g. CSE 2024-28" />
                </div>
                <div className="form-group">
                  <label className="form-label">Department</label>
                  <select className="form-select" value={form.departmentId} onChange={(e) => setForm({ ...form, departmentId: e.target.value })} required>
                    <option value="">Select Department</option>
                    {departments.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
                  </select>
                </div>
                <div className="form-group">
                  <label className="form-label">Degree</label>
                  <input className="form-input" value={form.degree} onChange={(e) => setForm({ ...form, degree: e.target.value })} required placeholder="e.g. B.Tech" />
                </div>
                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">Start Year</label>
                    <input className="form-input" type="number" value={form.startYear} onChange={(e) => setForm({ ...form, startYear: e.target.value })} required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">End Year</label>
                    <input className="form-input" type="number" value={form.endYear} onChange={(e) => setForm({ ...form, endYear: e.target.value })} required />
                  </div>
                </div>
              </div>
              <div className="modal-footer">
                <button type="button" className="btn btn-secondary" onClick={() => setShowModal(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary" disabled={saving}>{saving ? 'Saving...' : editing ? 'Update' : 'Create'}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <ConfirmDialog
        open={!!deleteTarget}
        title="Delete Batch?"
        message="This will soft-delete the batch. Related sections and students will need to be reassigned."
        onConfirm={handleDelete}
        onCancel={() => setDeleteTarget(null)}
        loading={deleting}
      />
    </div>
  );
}

import { useState, useEffect } from 'react';
import client from '../../api/client';
import ConfirmDialog from '../../components/ConfirmDialog';
import SyllabusEditor from '../../components/SyllabusEditor';
import { HiOutlinePlus, HiOutlinePencil, HiOutlineTrash, HiOutlineExclamation } from 'react-icons/hi';

const EMPTY_FORM = {
  code: '', name: '', credits: '3', semester: '1', type: 'theory',
  isMandatory: false,
  departments: [], // [{ departmentId, units: [] }]
};

export default function ManageCourses() {
  const [courses, setCourses] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState(EMPTY_FORM);
  const [saving, setSaving] = useState(false);
  const [filterDept, setFilterDept] = useState('');
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [deleting, setDeleting] = useState(false);
  const [error, setError] = useState('');
  const [activeTab, setActiveTab] = useState(0); // for mandatory course dept tabs

  // Syllabus editor modal (for editing syllabus of an existing course)
  const [syllabusModal, setSyllabusModal] = useState(null); // { courseId, departmentId, departmentName, units }
  const [savingSyllabus, setSavingSyllabus] = useState(false);

  const fetchData = async () => {
    try {
      const [courseRes, deptRes] = await Promise.all([
        client.get('/admin/courses', { params: filterDept ? { departmentId: filterDept } : {} }),
        client.get('/admin/departments'),
      ]);
      setCourses(courseRes.data.courses);
      setDepartments(deptRes.data.departments);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  };

  useEffect(() => { fetchData(); }, [filterDept]);

  useEffect(() => {
    if (error) {
      const t = setTimeout(() => setError(''), 4000);
      return () => clearTimeout(t);
    }
  }, [error]);

  const openCreate = () => {
    setEditing(null);
    setError('');
    setActiveTab(0);
    setForm({
      ...EMPTY_FORM,
      departments: departments.length > 0 ? [{ departmentId: departments[0].id, units: [] }] : [],
    });
    setShowModal(true);
  };

  const openEdit = (c) => {
    setEditing(c);
    setError('');
    setForm({
      code: c.code,
      name: c.name,
      credits: c.credits.toString(),
      semester: c.semester.toString(),
      type: c.type,
      isMandatory: c.isMandatory,
      departments: [], // not editable on edit - only shared fields
    });
    setShowModal(true);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    setError('');
    try {
      if (editing) {
        // Edit: only shared fields
        await client.put(`/admin/courses/${editing.id}`, {
          code: form.code, name: form.name, credits: form.credits,
          semester: form.semester, type: form.type,
        });
      } else {
        // Create: include departments + syllabus
        await client.post('/admin/courses', {
          code: form.code, name: form.name, credits: form.credits,
          semester: form.semester, type: form.type,
          isMandatory: form.isMandatory,
          departments: form.departments,
        });
      }
      setShowModal(false);
      fetchData();
    } catch (err) {
      setError(err.response?.data?.error || err.response?.data?.message || 'Failed to save course');
    }
    finally { setSaving(false); }
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    setDeleting(true);
    try {
      await client.delete(`/admin/courses/${deleteTarget}`);
      setDeleteTarget(null);
      fetchData();
    } catch (err) {
      alert(err.response?.data?.error || 'Failed to delete course');
    } finally {
      setDeleting(false);
    }
  };

  // ─── Syllabus modal handlers ───
  const openSyllabusEditor = (courseId, departmentId, departmentName, existingUnits) => {
    setSyllabusModal({
      courseId, departmentId, departmentName,
      units: (existingUnits || []).map((u) => ({
        number: u.number,
        title: u.title,
        hours: u.hours || '',
        topics: (u.topics || []).map((t) => ({
          order: t.order,
          title: t.title,
          description: t.description || '',
        })),
      })),
    });
  };

  const saveSyllabus = async () => {
    if (!syllabusModal) return;
    setSavingSyllabus(true);
    try {
      await client.put(
        `/admin/courses/${syllabusModal.courseId}/departments/${syllabusModal.departmentId}/syllabus`,
        { units: syllabusModal.units }
      );
      setSyllabusModal(null);
      fetchData();
    } catch (err) {
      alert(err.response?.data?.error || 'Failed to save syllabus');
    } finally {
      setSavingSyllabus(false);
    }
  };

  // ─── Form department helpers (create mode) ───
  const setDeptUnits = (deptIdx, units) => {
    const updated = form.departments.map((d, i) => (i === deptIdx ? { ...d, units } : d));
    setForm({ ...form, departments: updated });
  };

  const setDeptId = (deptIdx, departmentId) => {
    const updated = form.departments.map((d, i) => (i === deptIdx ? { ...d, departmentId } : d));
    setForm({ ...form, departments: updated });
  };

  const toggleMandatory = (val) => {
    if (val) {
      // Mandatory: one tab per department
      setForm({
        ...form,
        isMandatory: true,
        departments: departments.map((d) => ({ departmentId: d.id, units: [] })),
      });
      setActiveTab(0);
    } else {
      // Dept-specific: single department
      setForm({
        ...form,
        isMandatory: false,
        departments: [{ departmentId: departments[0]?.id || '', units: [] }],
      });
    }
  };

  const copyFromDept = (targetIdx, sourceIdx) => {
    if (sourceIdx === '' || sourceIdx === undefined) return;
    const src = form.departments[parseInt(sourceIdx)];
    if (!src) return;
    const updated = form.departments.map((d, i) =>
      i === targetIdx ? { ...d, units: JSON.parse(JSON.stringify(src.units)) } : d
    );
    setForm({ ...form, departments: updated });
  };

  if (loading) return <div className="loading-container"><div className="spinner spinner-lg" /></div>;

  const typeColor = { theory: 'badge-sky', lab: 'badge-purple', elective: 'badge-amber' };

  return (
    <div>
      <div className="page-header">
        <div><h1>Courses</h1><p className="page-subtitle">Manage academic courses</p></div>
        <button className="btn btn-primary" onClick={openCreate}><HiOutlinePlus /> Add Course</button>
      </div>

      <div className="toolbar">
        <div className="filter-group">
          <select className="form-select" value={filterDept} onChange={(e) => setFilterDept(e.target.value)} style={{ width: 'auto' }}>
            <option value="">All Departments</option>
            {departments.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
          </select>
        </div>
      </div>

      <div className="card">
        <div className="data-table-wrapper">
          <table className="data-table">
            <thead><tr>
              <th>Code</th><th>Name</th><th>Departments</th><th>Credits</th>
              <th>Semester</th><th>Type</th><th>Status</th><th>Actions</th>
            </tr></thead>
            <tbody>
              {courses.length === 0 ? (
                <tr><td colSpan="8"><div className="empty-state"><p>No courses yet.</p></div></td></tr>
              ) : courses.map((c) => (
                <tr key={c.id}>
                  <td><span className="badge badge-sky">{c.code}</span></td>
                  <td style={{ fontWeight: 500 }}>{c.name}</td>
                  <td>
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: '4px' }}>
                      {c.isMandatory && (
                        <span className="badge badge-purple" style={{ fontSize: '0.7rem' }}>Mandatory</span>
                      )}
                      {(c.departments || []).map((d) => (
                        <span key={d.id} className="badge badge-sky" style={{ fontSize: '0.7rem' }}>{d.code || d.name}</span>
                      ))}
                    </div>
                  </td>
                  <td>{c.credits}</td>
                  <td>Sem {c.semester}</td>
                  <td><span className={`badge ${typeColor[c.type] || 'badge-gray'}`}>{c.type}</span></td>
                  <td>
                    {c.needsSyllabusCount > 0 && (
                      <button
                        className="badge badge-amber"
                        style={{
                          cursor: 'pointer', border: 'none', display: 'inline-flex',
                          alignItems: 'center', gap: '3px', fontSize: '0.72rem',
                        }}
                        title="Click to add syllabus for departments missing it"
                        onClick={() => {
                          // Find first dept with no units
                          const cd = c.courseDepartments?.find((cd) => cd._count?.units === 0);
                          if (cd) openSyllabusEditor(c.id, cd.department.id, cd.department.name, []);
                        }}
                      >
                        <HiOutlineExclamation size={12} />
                        {c.needsSyllabusCount} need{c.needsSyllabusCount === 1 ? 's' : ''} syllabus
                      </button>
                    )}
                    {c.needsSyllabusCount === 0 && c.courseDepartments?.length > 0 && (
                      <span style={{ fontSize: '0.78rem', color: '#22c55e' }}>✓</span>
                    )}
                  </td>
                  <td className="actions">
                    <button className="btn btn-ghost btn-sm" onClick={() => openEdit(c)} title="Edit"><HiOutlinePencil /></button>
                    {/* Syllabus edit per-department */}
                    {c.courseDepartments?.map((cd) => (
                      <button
                        key={cd.department.id}
                        className="btn btn-ghost btn-sm"
                        onClick={() => openSyllabusEditor(c.id, cd.department.id, cd.department.name, cd.units || [])}
                        title={`Edit syllabus for ${cd.department.name}`}
                        style={{ fontSize: '0.7rem', padding: '2px 6px' }}
                      >
                        📋 {cd.department.code}
                      </button>
                    ))}
                    <button className="btn btn-ghost btn-sm" onClick={() => setDeleteTarget(c.id)} title="Delete" style={{ color: 'var(--color-danger)' }}><HiOutlineTrash /></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* ─── Create / Edit Course Modal ─── */}
      {showModal && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()} style={{ maxWidth: editing ? '560px' : '720px' }}>
            <div className="modal-header">
              <h2>{editing ? 'Edit Course' : 'Add Course'}</h2>
              <button className="btn btn-ghost" onClick={() => setShowModal(false)}>✕</button>
            </div>
            <form onSubmit={handleSubmit}>
              <div className="modal-body" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)', maxHeight: '70vh', overflowY: 'auto' }}>
                {error && (
                  <div style={{
                    padding: '10px 14px', borderRadius: '8px',
                    backgroundColor: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626',
                    fontSize: '0.9rem', fontWeight: 500,
                  }}>
                    ⚠️ {error}
                  </div>
                )}

                {/* Mandatory toggle (only on create) */}
                {!editing && (
                  <div className="form-group">
                    <label className="form-label">Course Scope</label>
                    <div style={{ display: 'flex', gap: '12px' }}>
                      <label style={{
                        display: 'flex', alignItems: 'center', gap: '6px', padding: '8px 16px',
                        borderRadius: '8px', cursor: 'pointer',
                        border: !form.isMandatory ? '2px solid #818cf8' : '2px solid #e2e8f0',
                        background: !form.isMandatory ? '#f0f0ff' : '#fff',
                        transition: 'all 0.15s',
                      }}>
                        <input
                          type="radio" name="scope" checked={!form.isMandatory}
                          onChange={() => toggleMandatory(false)}
                          style={{ accentColor: '#818cf8' }}
                        />
                        <span style={{ fontWeight: 500, fontSize: '0.9rem' }}>Department-specific</span>
                      </label>
                      <label style={{
                        display: 'flex', alignItems: 'center', gap: '6px', padding: '8px 16px',
                        borderRadius: '8px', cursor: 'pointer',
                        border: form.isMandatory ? '2px solid #818cf8' : '2px solid #e2e8f0',
                        background: form.isMandatory ? '#f0f0ff' : '#fff',
                        transition: 'all 0.15s',
                      }}>
                        <input
                          type="radio" name="scope" checked={form.isMandatory}
                          onChange={() => toggleMandatory(true)}
                          style={{ accentColor: '#818cf8' }}
                        />
                        <span style={{ fontWeight: 500, fontSize: '0.9rem' }}>Mandatory (all departments)</span>
                      </label>
                    </div>
                  </div>
                )}

                {/* Show locked badge on edit */}
                {editing && (
                  <div style={{
                    display: 'flex', alignItems: 'center', gap: '8px',
                    padding: '8px 12px', borderRadius: '8px',
                    background: form.isMandatory ? '#f0f0ff' : '#f0f7ff',
                    border: '1px solid #e2e8f0',
                  }}>
                    <span className={`badge ${form.isMandatory ? 'badge-purple' : 'badge-sky'}`}>
                      {form.isMandatory ? 'Mandatory' : 'Department-specific'}
                    </span>
                    <span style={{ fontSize: '0.8rem', color: '#64748b' }}>Cannot be changed after creation</span>
                  </div>
                )}

                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">Course Code</label>
                    <input className="form-input" value={form.code} onChange={(e) => setForm({ ...form, code: e.target.value })} required placeholder="e.g. CS101" />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Course Name</label>
                    <input className="form-input" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required placeholder="e.g. Data Structures" />
                  </div>
                </div>

                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">Credits</label>
                    <input className="form-input" type="number" min="1" max="10" value={form.credits} onChange={(e) => setForm({ ...form, credits: e.target.value })} required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Semester</label>
                    <input className="form-input" type="number" min="1" max="8" value={form.semester} onChange={(e) => setForm({ ...form, semester: e.target.value })} required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Type</label>
                    <select className="form-select" value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })}>
                      <option value="theory">Theory</option>
                      <option value="lab">Lab</option>
                      <option value="elective">Elective</option>
                    </select>
                  </div>
                </div>

                {/* Department + Syllabus section (create only) */}
                {!editing && (
                  <>
                    {!form.isMandatory ? (
                      /* ── Department-specific: single dept + syllabus ── */
                      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                        <div className="form-group">
                          <label className="form-label">Department</label>
                          <select
                            className="form-select"
                            value={form.departments[0]?.departmentId || ''}
                            onChange={(e) => setDeptId(0, e.target.value)}
                            required
                          >
                            <option value="">Select Department</option>
                            {departments.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
                          </select>
                        </div>
                        <div className="form-group">
                          <label className="form-label" style={{ marginBottom: '6px' }}>Syllabus (optional)</label>
                          <SyllabusEditor
                            units={form.departments[0]?.units || []}
                            onChange={(units) => setDeptUnits(0, units)}
                          />
                        </div>
                      </div>
                    ) : (
                      /* ── Mandatory: tabs for each department ── */
                      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                        <label className="form-label">Syllabus per Department</label>
                        {/* Tab bar */}
                        <div style={{
                          display: 'flex', flexWrap: 'wrap', gap: '4px',
                          borderBottom: '2px solid #e2e8f0', paddingBottom: '0',
                        }}>
                          {form.departments.map((dept, idx) => {
                            const d = departments.find((x) => x.id === dept.departmentId);
                            const hasContent = dept.units.length > 0;
                            return (
                              <button
                                key={dept.departmentId}
                                type="button"
                                onClick={() => setActiveTab(idx)}
                                style={{
                                  padding: '6px 14px', fontSize: '0.82rem', fontWeight: 500,
                                  border: 'none', borderBottom: activeTab === idx ? '2px solid #818cf8' : '2px solid transparent',
                                  background: activeTab === idx ? '#f0f0ff' : 'transparent',
                                  color: activeTab === idx ? '#818cf8' : '#64748b',
                                  cursor: 'pointer', borderRadius: '6px 6px 0 0',
                                  transition: 'all 0.15s',
                                  position: 'relative',
                                }}
                              >
                                {d?.code || d?.name || 'Dept'}
                                {!hasContent && (
                                  <span style={{
                                    position: 'absolute', top: '-2px', right: '-2px',
                                    width: '8px', height: '8px', borderRadius: '50%',
                                    background: '#f59e0b',
                                  }} />
                                )}
                              </button>
                            );
                          })}
                        </div>

                        {/* Active tab content */}
                        {form.departments[activeTab] && (
                          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                            {/* Copy from dropdown */}
                            {form.departments.length > 1 && (
                              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                <span style={{ fontSize: '0.8rem', color: '#64748b' }}>Copy syllabus from:</span>
                                <select
                                  className="form-select"
                                  style={{ width: 'auto', padding: '4px 8px', fontSize: '0.82rem' }}
                                  value=""
                                  onChange={(e) => copyFromDept(activeTab, e.target.value)}
                                >
                                  <option value="">Select...</option>
                                  {form.departments.map((dept, idx) => {
                                    if (idx === activeTab) return null;
                                    const d = departments.find((x) => x.id === dept.departmentId);
                                    return (
                                      <option key={idx} value={idx} disabled={dept.units.length === 0}>
                                        {d?.code || d?.name} {dept.units.length === 0 ? '(empty)' : `(${dept.units.length} units)`}
                                      </option>
                                    );
                                  })}
                                </select>
                              </div>
                            )}
                            <SyllabusEditor
                              units={form.departments[activeTab].units}
                              onChange={(units) => setDeptUnits(activeTab, units)}
                            />
                          </div>
                        )}
                      </div>
                    )}
                  </>
                )}
              </div>
              <div className="modal-footer">
                <button type="button" className="btn btn-secondary" onClick={() => setShowModal(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary" disabled={saving}>{saving ? 'Saving...' : editing ? 'Update' : 'Create'}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ─── Syllabus Editor Modal (for existing courses) ─── */}
      {syllabusModal && (
        <div className="modal-overlay" onClick={() => setSyllabusModal(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()} style={{ maxWidth: '640px' }}>
            <div className="modal-header">
              <h2>
                Edit Syllabus
                <span style={{ fontSize: '0.85rem', fontWeight: 400, color: '#64748b', marginLeft: '8px' }}>
                  — {syllabusModal.departmentName}
                </span>
              </h2>
              <button className="btn btn-ghost" onClick={() => setSyllabusModal(null)}>✕</button>
            </div>
            <div className="modal-body" style={{ maxHeight: '65vh', overflowY: 'auto' }}>
              <SyllabusEditor
                units={syllabusModal.units}
                onChange={(units) => setSyllabusModal({ ...syllabusModal, units })}
              />
            </div>
            <div className="modal-footer">
              <button type="button" className="btn btn-secondary" onClick={() => setSyllabusModal(null)}>Cancel</button>
              <button type="button" className="btn btn-primary" onClick={saveSyllabus} disabled={savingSyllabus}>
                {savingSyllabus ? 'Saving...' : 'Save Syllabus'}
              </button>
            </div>
          </div>
        </div>
      )}

      <ConfirmDialog
        open={!!deleteTarget}
        title="Delete Course?"
        message="This will soft-delete the course. Related class assignments, marks, and attendance records may be affected."
        onConfirm={handleDelete}
        onCancel={() => setDeleteTarget(null)}
        loading={deleting}
      />
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import client from '../../api/client';
import {
  HiOutlineMail, HiOutlineMailOpen, HiOutlineSearch,
  HiOutlineFilter, HiOutlineArchive, HiOutlineReply,
  HiOutlineTag, HiOutlineClock, HiOutlineUser,
  HiOutlineAcademicCap, HiOutlineChevronLeft,
  HiOutlineCheckCircle, HiOutlineExclamation,
} from 'react-icons/hi';

const CATEGORIES = [
  { value: 'all', label: 'All Categories' },
  { value: 'general', label: 'General', color: 'var(--color-sky-500)' },
  { value: 'academics', label: 'Academics', color: 'var(--color-purple-500)' },
  { value: 'infrastructure', label: 'Infrastructure', color: 'var(--color-warning)' },
  { value: 'faculty', label: 'Faculty', color: 'var(--color-indigo-500)' },
  { value: 'suggestion', label: 'Suggestion', color: 'var(--color-success)' },
  { value: 'complaint', label: 'Complaint', color: 'var(--color-danger)' },
  { value: 'other', label: 'Other', color: 'var(--color-gray-500)' },
];

const STATUS_TABS = [
  { value: 'unread', label: 'Unread', icon: HiOutlineMail },
  { value: 'read', label: 'Read', icon: HiOutlineMailOpen },
  { value: 'archived', label: 'Archived', icon: HiOutlineArchive },
];

export default function ManageFeedback() {
  const [feedbacks, setFeedbacks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [total, setTotal] = useState(0);
  const [unreadCount, setUnreadCount] = useState(0);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [statusFilter, setStatusFilter] = useState('unread');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [search, setSearch] = useState('');
  const [selectedFeedback, setSelectedFeedback] = useState(null);
  const [replyText, setReplyText] = useState('');
  const [replying, setReplying] = useState(false);
  const [actionLoading, setActionLoading] = useState(null);

  const fetchFeedbacks = useCallback(async () => {
    setLoading(true);
    try {
      const params = { status: statusFilter, category: categoryFilter, search, page, limit: 15 };
      const { data } = await client.get('/admin/feedback', { params });
      setFeedbacks(data.feedbacks);
      setTotal(data.total);
      setTotalPages(data.totalPages);
      setUnreadCount(data.unreadCount);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  }, [statusFilter, categoryFilter, search, page]);

  useEffect(() => { fetchFeedbacks(); }, [fetchFeedbacks]);

  const openFeedback = async (id) => {
    try {
      const { data } = await client.get(`/admin/feedback/${id}`);
      setSelectedFeedback(data.feedback);
      setReplyText(data.feedback.adminReply || '');
      // Refresh list to update read status
      fetchFeedbacks();
    } catch (err) { console.error(err); }
  };

  const handleReply = async () => {
    if (!replyText.trim()) return;
    setReplying(true);
    try {
      const { data } = await client.put(`/admin/feedback/${selectedFeedback.id}/reply`, { reply: replyText });
      setSelectedFeedback({ ...selectedFeedback, adminReply: data.feedback.adminReply, repliedAt: data.feedback.repliedAt });
      fetchFeedbacks();
    } catch (err) { console.error(err); alert(err.response?.data?.error || 'Failed to send reply'); }
    finally { setReplying(false); }
  };

  const handleArchive = async (id) => {
    setActionLoading(id);
    try {
      await client.put(`/admin/feedback/${id}/archive`);
      if (selectedFeedback?.id === id) setSelectedFeedback(null);
      fetchFeedbacks();
    } catch (err) { console.error(err); }
    finally { setActionLoading(null); }
  };

  const handleToggleRead = async (id) => {
    setActionLoading(id);
    try {
      await client.put(`/admin/feedback/${id}/read`);
      if (selectedFeedback?.id === id) {
        setSelectedFeedback({ ...selectedFeedback, isRead: !selectedFeedback.isRead });
      }
      fetchFeedbacks();
    } catch (err) { console.error(err); }
    finally { setActionLoading(null); }
  };

  const getCategoryInfo = (cat) => CATEGORIES.find((c) => c.value === cat) || CATEGORIES[1];

  const formatDate = (d) => {
    if (!d) return '—';
    const date = new Date(d);
    const now = new Date();
    const diff = now - date;
    if (diff < 60 * 1000) return 'Just now';
    if (diff < 60 * 60 * 1000) return `${Math.floor(diff / 60000)}m ago`;
    if (diff < 24 * 60 * 60 * 1000) return `${Math.floor(diff / 3600000)}h ago`;
    if (diff < 7 * 24 * 60 * 60 * 1000) return `${Math.floor(diff / 86400000)}d ago`;
    return date.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
  };

  const formatFullDate = (d) => {
    if (!d) return '—';
    return new Date(d).toLocaleDateString('en-IN', {
      day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit',
    });
  };

  // ─── Detail View ─────────────────────────────
  if (selectedFeedback) {
    const fb = selectedFeedback;
    const cat = getCategoryInfo(fb.category);
    return (
      <div>
        <button
          className="btn btn-ghost"
          onClick={() => setSelectedFeedback(null)}
          style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', marginBottom: 'var(--space-4)' }}
        >
          <HiOutlineChevronLeft size={18} /> Back to Inbox
        </button>

        <div className="card">
          {/* Feedback header */}
          <div style={{
            padding: 'var(--space-5) var(--space-6)',
            borderBottom: '1px solid var(--color-gray-100)',
            background: 'rgba(79, 70, 229, 0.03)',
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 'var(--space-4)', flexWrap: 'wrap' }}>
              <div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', marginBottom: 'var(--space-2)' }}>
                  <span style={{
                    fontSize: 'var(--font-xs)', padding: '2px 10px', borderRadius: 'var(--radius-full)',
                    background: `${cat.color}15`, color: cat.color, fontWeight: 500,
                  }}>
                    {cat.label}
                  </span>
                  {fb.adminReply && (
                    <span className="badge badge-success" style={{ fontSize: 'var(--font-xs)' }}>Replied</span>
                  )}
                </div>
                <h2 style={{ fontSize: 'var(--font-xl)', fontWeight: 700 }}>{fb.subject}</h2>
                <div style={{ fontSize: 'var(--font-sm)', color: 'var(--color-gray-400)', marginTop: 'var(--space-1)' }}>
                  <HiOutlineClock size={14} style={{ verticalAlign: 'middle', marginRight: 4 }} />
                  {formatFullDate(fb.createdAt)}
                </div>
              </div>
              <div style={{ display: 'flex', gap: 'var(--space-2)' }}>
                <button
                  className="btn btn-ghost"
                  onClick={() => handleToggleRead(fb.id)}
                  title={fb.isRead ? 'Mark as unread' : 'Mark as read'}
                  style={{ fontSize: 'var(--font-sm)' }}
                >
                  {fb.isRead ? <HiOutlineMail size={16} /> : <HiOutlineMailOpen size={16} />}
                  {fb.isRead ? 'Unread' : 'Read'}
                </button>
                <button
                  className="btn btn-ghost"
                  onClick={() => handleArchive(fb.id)}
                  title={fb.isArchived ? 'Unarchive' : 'Archive'}
                  style={{ fontSize: 'var(--font-sm)' }}
                >
                  <HiOutlineArchive size={16} />
                  {fb.isArchived ? 'Unarchive' : 'Archive'}
                </button>
              </div>
            </div>
          </div>

          {/* Student info */}
          {fb.student && (
            <div style={{
              padding: 'var(--space-4) var(--space-6)',
              borderBottom: '1px solid var(--color-gray-100)',
              display: 'flex',
              alignItems: 'center',
              gap: 'var(--space-4)',
              flexWrap: 'wrap',
              background: 'var(--color-gray-50)',
            }}>
              <div style={{
                width: 40, height: 40, borderRadius: 'var(--radius-full)',
                background: 'var(--gradient-primary)',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                color: '#fff', fontWeight: 600, fontSize: 'var(--font-sm)',
              }}>
                {fb.student.firstName?.charAt(0)}{fb.student.lastName?.charAt(0)}
              </div>
              <div>
                <div style={{ fontWeight: 600 }}>{fb.student.firstName} {fb.student.lastName}</div>
                <div style={{ fontSize: 'var(--font-xs)', color: 'var(--color-gray-500)' }}>
                  {fb.student.enrollmentNo} · Semester {fb.student.semester}
                  {fb.student.batch && ` · ${fb.student.batch.department?.name}`}
                  {fb.student.section && ` · ${fb.student.section.name}`}
                </div>
              </div>
              {fb.student.user?.email && (
                <div style={{ marginLeft: 'auto', fontSize: 'var(--font-xs)', color: 'var(--color-gray-400)' }}>
                  {fb.student.user.email}
                </div>
              )}
            </div>
          )}

          {/* Message body */}
          <div style={{ padding: 'var(--space-6)' }}>
            <div style={{
              padding: 'var(--space-5)',
              background: 'var(--color-gray-50)',
              borderRadius: 'var(--radius-lg)',
              fontSize: 'var(--font-base)',
              lineHeight: 1.8,
              whiteSpace: 'pre-wrap',
              color: 'var(--color-gray-700)',
            }}>
              {fb.message}
            </div>

            {/* Existing reply */}
            {fb.adminReply && (
              <div style={{
                marginTop: 'var(--space-5)',
                padding: 'var(--space-5)',
                background: 'rgba(37, 99, 235, 0.05)',
                borderRadius: 'var(--radius-lg)',
                border: '1px solid rgba(16, 185, 129, 0.2)',
              }}>
                <div style={{
                  display: 'flex', alignItems: 'center', gap: 'var(--space-2)',
                  marginBottom: 'var(--space-3)',
                  color: 'var(--color-success)', fontWeight: 600,
                }}>
                  <HiOutlineCheckCircle size={18} />
                  Your Reply
                  {fb.repliedAt && (
                    <span style={{ fontWeight: 400, color: 'var(--color-gray-400)', fontSize: 'var(--font-xs)' }}>
                      · {formatFullDate(fb.repliedAt)}
                    </span>
                  )}
                </div>
                <div style={{
                  fontSize: 'var(--font-sm)', lineHeight: 1.7,
                  whiteSpace: 'pre-wrap', color: 'var(--color-gray-700)',
                }}>
                  {fb.adminReply}
                </div>
              </div>
            )}

            {/* Reply form */}
            <div style={{ marginTop: 'var(--space-5)' }}>
              <label className="form-label" style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}>
                <HiOutlineReply size={16} />
                {fb.adminReply ? 'Update Reply' : 'Reply to Student'}
              </label>
              <textarea
                className="form-input"
                rows={4}
                placeholder="Write your response..."
                value={replyText}
                onChange={(e) => setReplyText(e.target.value)}
                style={{ resize: 'vertical', minHeight: 100 }}
              />
              <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: 'var(--space-3)' }}>
                <button
                  className="btn btn-primary"
                  onClick={handleReply}
                  disabled={replying || !replyText.trim()}
                  style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)' }}
                >
                  {replying ? <div className="spinner" /> : <HiOutlineReply size={16} />}
                  {replying ? 'Sending...' : fb.adminReply ? 'Update Reply' : 'Send Reply'}
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // ─── List View ───────────────────────────────
  return (
    <div>
      {/* Header */}
      <div className="page-header">
        <h1 style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
          <HiOutlineMail size={28} style={{ color: 'var(--color-purple-500)' }} />
          Student Feedback
          {unreadCount > 0 && (
            <span style={{
              background: 'var(--color-danger)',
              color: '#fff',
              fontSize: 'var(--font-xs)',
              fontWeight: 600,
              padding: '2px 8px',
              borderRadius: 'var(--radius-full)',
              minWidth: 20,
              textAlign: 'center',
            }}>
              {unreadCount}
            </span>
          )}
        </h1>
        <p className="page-subtitle">View and respond to student thoughts, suggestions, and feedback</p>
      </div>

      {/* Status tabs */}
      <div style={{
        display: 'flex',
        gap: 'var(--space-1)',
        marginBottom: 'var(--space-5)',
        background: 'var(--color-gray-100)',
        borderRadius: 'var(--radius-lg)',
        padding: 'var(--space-1)',
        width: 'fit-content',
      }}>
        {STATUS_TABS.map(({ value, label, icon: Icon }) => (
          <button
            key={value}
            onClick={() => { setStatusFilter(value); setPage(1); }}
            style={{
              padding: 'var(--space-2) var(--space-4)',
              borderRadius: 'var(--radius-md)',
              border: 'none',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              gap: 'var(--space-2)',
              fontSize: 'var(--font-sm)',
              fontWeight: statusFilter === value ? 600 : 400,
              background: statusFilter === value ? '#fff' : 'transparent',
              color: statusFilter === value ? 'var(--color-purple-600)' : 'var(--color-gray-500)',
              boxShadow: statusFilter === value ? 'var(--shadow-sm)' : 'none',
              transition: 'all var(--transition-fast)',
            }}
          >
            <Icon size={16} />
            {label}
            {value === 'unread' && unreadCount > 0 && (
              <span style={{
                background: 'var(--color-danger)',
                color: '#fff',
                fontSize: '10px',
                padding: '0 5px',
                borderRadius: 'var(--radius-full)',
                fontWeight: 600,
              }}>
                {unreadCount}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* Filters */}
      <div style={{ display: 'flex', gap: 'var(--space-3)', marginBottom: 'var(--space-5)', flexWrap: 'wrap' }}>
        <div style={{ position: 'relative', flex: '1 1 280px' }}>
          <HiOutlineSearch size={16} style={{
            position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)',
            color: 'var(--color-gray-400)',
          }} />
          <input
            className="form-input"
            placeholder="Search by subject, message, or student..."
            value={search}
            onChange={(e) => { setSearch(e.target.value); setPage(1); }}
            style={{ paddingLeft: 36 }}
          />
        </div>
        <select
          className="form-input"
          value={categoryFilter}
          onChange={(e) => { setCategoryFilter(e.target.value); setPage(1); }}
          style={{ width: 'auto', minWidth: 180 }}
        >
          {CATEGORIES.map((c) => (
            <option key={c.value} value={c.value}>{c.label}</option>
          ))}
        </select>
      </div>

      {/* Feedback list */}
      <div className="card">
        {loading ? (
          <div className="loading-container"><div className="spinner spinner-lg" /></div>
        ) : feedbacks.length === 0 ? (
          <div style={{
            textAlign: 'center',
            padding: 'var(--space-10) var(--space-6)',
            color: 'var(--color-gray-400)',
          }}>
            <HiOutlineMail size={48} style={{ marginBottom: 'var(--space-3)', opacity: 0.5 }} />
            <p style={{ fontSize: 'var(--font-lg)', fontWeight: 500 }}>No feedback found</p>
            <p style={{ fontSize: 'var(--font-sm)' }}>
              {statusFilter === 'unread' ? 'All caught up! No unread feedback.' : 'No feedback matching your filters.'}
            </p>
          </div>
        ) : (
          <>
            {feedbacks.map((fb) => {
              const cat = getCategoryInfo(fb.category);
              return (
                <div
                  key={fb.id}
                  onClick={() => openFeedback(fb.id)}
                  style={{
                    padding: 'var(--space-4) var(--space-5)',
                    borderBottom: '1px solid var(--color-gray-50)',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    gap: 'var(--space-4)',
                    transition: 'background var(--transition-fast)',
                    background: !fb.isRead ? 'rgba(139, 92, 246, 0.02)' : 'transparent',
                    fontWeight: !fb.isRead ? 500 : 400,
                  }}
                  onMouseOver={(e) => e.currentTarget.style.background = 'var(--color-gray-50)'}
                  onMouseOut={(e) => e.currentTarget.style.background = !fb.isRead ? 'rgba(139, 92, 246, 0.02)' : 'transparent'}
                >
                  {/* Unread dot */}
                  <div style={{
                    width: 8, height: 8, borderRadius: '50%', flexShrink: 0,
                    background: !fb.isRead ? 'var(--color-purple-500)' : 'transparent',
                  }} />

                  {/* Student avatar */}
                  <div style={{
                    width: 36, height: 36, borderRadius: 'var(--radius-full)', flexShrink: 0,
                    background: 'var(--gradient-primary)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    color: '#fff', fontSize: 'var(--font-xs)', fontWeight: 600,
                  }}>
                    {fb.student?.firstName?.charAt(0)}{fb.student?.lastName?.charAt(0)}
                  </div>

                  {/* Content */}
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-2)', marginBottom: 2 }}>
                      <span style={{ fontSize: 'var(--font-sm)', fontWeight: 600, color: 'var(--color-gray-900)' }}>
                        {fb.student?.firstName} {fb.student?.lastName}
                      </span>
                      <span style={{ fontSize: 'var(--font-xs)', color: 'var(--color-gray-400)' }}>
                        {fb.student?.enrollmentNo}
                      </span>
                      <span style={{
                        fontSize: '10px', padding: '1px 6px', borderRadius: 'var(--radius-full)',
                        background: `${cat.color}15`, color: cat.color, fontWeight: 500,
                      }}>
                        {cat.label}
                      </span>
                    </div>
                    <div style={{
                      fontSize: 'var(--font-sm)',
                      color: !fb.isRead ? 'var(--color-gray-900)' : 'var(--color-gray-600)',
                      fontWeight: !fb.isRead ? 600 : 400,
                      overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                    }}>
                      {fb.subject}
                    </div>
                    <div style={{
                      fontSize: 'var(--font-xs)', color: 'var(--color-gray-400)',
                      overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                      marginTop: 2,
                    }}>
                      {fb.message.substring(0, 100)}{fb.message.length > 100 ? '...' : ''}
                    </div>
                  </div>

                  {/* Meta */}
                  <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 'var(--space-1)', flexShrink: 0 }}>
                    <span style={{ fontSize: 'var(--font-xs)', color: 'var(--color-gray-400)', whiteSpace: 'nowrap' }}>
                      {formatDate(fb.createdAt)}
                    </span>
                    {fb.adminReply && (
                      <span style={{
                        fontSize: '10px', padding: '1px 6px', borderRadius: 'var(--radius-full)',
                        background: 'rgba(16, 185, 129, 0.1)', color: 'var(--color-success)', fontWeight: 500,
                        display: 'flex', alignItems: 'center', gap: 2,
                      }}>
                        <HiOutlineReply size={10} /> Replied
                      </span>
                    )}
                  </div>

                  {/* Actions */}
                  <div style={{ display: 'flex', gap: 'var(--space-1)', flexShrink: 0 }} onClick={(e) => e.stopPropagation()}>
                    <button
                      className="btn btn-ghost"
                      style={{ padding: 'var(--space-1)' }}
                      onClick={() => handleArchive(fb.id)}
                      title={fb.isArchived ? 'Unarchive' : 'Archive'}
                      disabled={actionLoading === fb.id}
                    >
                      <HiOutlineArchive size={16} />
                    </button>
                  </div>
                </div>
              );
            })}

            {/* Pagination */}
            {totalPages > 1 && (
              <div style={{
                padding: 'var(--space-4) var(--space-5)',
                display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                borderTop: '1px solid var(--color-gray-100)',
              }}>
                <span style={{ fontSize: 'var(--font-sm)', color: 'var(--color-gray-500)' }}>
                  Showing {(page - 1) * 15 + 1}–{Math.min(page * 15, total)} of {total}
                </span>
                <div style={{ display: 'flex', gap: 'var(--space-2)' }}>
                  <button className="btn btn-ghost" disabled={page <= 1} onClick={() => setPage(page - 1)}>Previous</button>
                  <button className="btn btn-ghost" disabled={page >= totalPages} onClick={() => setPage(page + 1)}>Next</button>
                </div>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import client from '../../api/client';
import ConfirmDialog from '../../components/ConfirmDialog';
import { HiOutlinePlus, HiOutlinePencil, HiOutlineTrash } from 'react-icons/hi';

export default function ManageSections() {
  const [sections, setSections] = useState([]);
  const [batches, setBatches] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({ name: '', batchId: '' });
  const [saving, setSaving] = useState(false);
  const [filterBatch, setFilterBatch] = useState('');
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [deleting, setDeleting] = useState(false);

  const fetchData = async () => {
    try {
      const [secRes, batchRes] = await Promise.all([
        client.get('/admin/sections', { params: filterBatch ? { batchId: filterBatch } : {} }),
        client.get('/admin/batches'),
      ]);
      setSections(secRes.data.sections);
      setBatches(batchRes.data.batches);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  };

  useEffect(() => { fetchData(); }, [filterBatch]);

  const openCreate = () => { setEditing(null); setForm({ name: '', batchId: batches[0]?.id || '' }); setShowModal(true); };
  const openEdit = (s) => { setEditing(s); setForm({ name: s.name, batchId: s.batchId }); setShowModal(true); };

  const handleSubmit = async (e) => {
    e.preventDefault(); setSaving(true);
    try {
      if (editing) await client.put(`/admin/sections/${editing.id}`, form);
      else await client.post('/admin/sections', form);
      setShowModal(false); fetchData();
    } catch (err) { alert(err.response?.data?.error || 'Error'); }
    finally { setSaving(false); }
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    setDeleting(true);
    try {
      await client.delete(`/admin/sections/${deleteTarget}`);
      setDeleteTarget(null);
      fetchData();
    } catch (err) {
      alert(err.response?.data?.error || 'Failed to delete section');
    } finally {
      setDeleting(false);
    }
  };

  if (loading) return <div className="loading-container"><div className="spinner spinner-lg" /></div>;

  return (
    <div>
      <div className="page-header">
        <div><h1>Sections</h1><p className="page-subtitle">Manage batch sections</p></div>
        <button className="btn btn-primary" onClick={openCreate}><HiOutlinePlus /> Add Section</button>
      </div>

      <div className="toolbar">
        <div className="filter-group">
          <select className="form-select" value={filterBatch} onChange={(e) => setFilterBatch(e.target.value)} style={{ width: 'auto' }}>
            <option value="">All Batches</option>
            {batches.map((b) => <option key={b.id} value={b.id}>{b.name}</option>)}
          </select>
        </div>
      </div>

      <div className="card">
        <div className="data-table-wrapper">
          <table className="data-table">
            <thead><tr><th>Name</th><th>Batch</th><th>Department</th><th>Students</th><th>Actions</th></tr></thead>
            <tbody>
              {sections.length === 0 ? (
                <tr><td colSpan="5"><div className="empty-state"><p>No sections yet.</p></div></td></tr>
              ) : sections.map((s) => (
                <tr key={s.id}>
                  <td style={{ fontWeight: 500 }}>{s.name}</td>
                  <td>{s.batch?.name}</td>
                  <td><span className="badge badge-purple">{s.batch?.department?.name}</span></td>
                  <td>{s._count?.students || 0}</td>
                  <td className="actions">
                    <button className="btn btn-ghost btn-sm" onClick={() => openEdit(s)} title="Edit"><HiOutlinePencil /></button>
                    <button className="btn btn-ghost btn-sm" onClick={() => setDeleteTarget(s.id)} title="Delete" style={{ color: 'var(--color-danger)' }}><HiOutlineTrash /></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {showModal && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header"><h2>{editing ? 'Edit Section' : 'Add Section'}</h2><button className="btn btn-ghost" onClick={() => setShowModal(false)}>✕</button></div>
            <form onSubmit={handleSubmit}>
              <div className="modal-body" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
                <div className="form-group">
                  <label className="form-label">Section Name</label>
                  <input className="form-input" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required placeholder="e.g. Section A" />
                </div>
                <div className="form-group">
                  <label className="form-label">Batch</label>
                  <select className="form-select" value={form.batchId} onChange={(e) => setForm({ ...form, batchId: e.target.value })} required>
                    <option value="">Select Batch</option>
                    {batches.map((b) => <option key={b.id} value={b.id}>{b.name}</option>)}
                  </select>
                </div>
              </div>
              <div className="modal-footer">
                <button type="button" className="btn btn-secondary" onClick={() => setShowModal(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary" disabled={saving}>{saving ? 'Saving...' : editing ? 'Update' : 'Create'}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <ConfirmDialog
        open={!!deleteTarget}
        title="Delete Section?"
        message="This will soft-delete the section. Students assigned to this section will need to be reassigned."
        onConfirm={handleDelete}
        onCancel={() => setDeleteTarget(null)}
        loading={deleting}
      />
    </div>
  );
}

import { useState, useEffect } from 'react';
import client from '../../api/client';
import ConfirmDialog from '../../components/ConfirmDialog';
import {
  HiOutlinePlus, HiOutlinePencil, HiOutlineTrash, HiOutlineEye,
  HiOutlineTag, HiOutlineX, HiOutlineLightBulb,
} from 'react-icons/hi';

export default function ManageSkillCourses() {
  const [courses, setCourses] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({
    title: '', description: '', categoryId: '', difficulty: 'beginner',
    duration: '', provider: '', link: '',
  });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [filterCat, setFilterCat] = useState('');
  const [filterDiff, setFilterDiff] = useState('');
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [deleting, setDeleting] = useState(false);

  // Category management
  const [showCatModal, setShowCatModal] = useState(false);
  const [catName, setCatName] = useState('');
  const [catSaving, setCatSaving] = useState(false);
  const [catError, setCatError] = useState('');
  const [catDeleteTarget, setCatDeleteTarget] = useState(null);

  // Enrollment viewer
  const [enrollments, setEnrollments] = useState(null);
  const [enrollCourse, setEnrollCourse] = useState(null);
  const [loadingEnroll, setLoadingEnroll] = useState(false);

  const fetchData = async () => {
    try {
      const params = {};
      if (filterCat) params.categoryId = filterCat;
      if (filterDiff) params.difficulty = filterDiff;
      const [courseRes, catRes] = await Promise.all([
        client.get('/admin/skill-courses', { params }),
        client.get('/admin/skill-course-categories'),
      ]);
      setCourses(courseRes.data.skillCourses);
      setCategories(catRes.data.categories);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  };

  useEffect(() => { fetchData(); }, [filterCat, filterDiff]);
  useEffect(() => { if (error) { const t = setTimeout(() => setError(''), 4000); return () => clearTimeout(t); } }, [error]);
  useEffect(() => { if (catError) { const t = setTimeout(() => setCatError(''), 4000); return () => clearTimeout(t); } }, [catError]);

  const openCreate = () => {
    setEditing(null); setError('');
    setForm({ title: '', description: '', categoryId: categories[0]?.id || '', difficulty: 'beginner', duration: '', provider: '', link: '' });
    setShowModal(true);
  };
  const openEdit = (c) => {
    setEditing(c); setError('');
    setForm({
      title: c.title, description: c.description, categoryId: c.categoryId,
      difficulty: c.difficulty, duration: c.duration,
      provider: c.provider || '', link: c.link || '',
    });
    setShowModal(true);
  };

  const handleSubmit = async (e) => {
    e.preventDefault(); setSaving(true); setError('');
    try {
      if (editing) await client.put(`/admin/skill-courses/${editing.id}`, form);
      else await client.post('/admin/skill-courses', form);
      setShowModal(false); fetchData();
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to save skill course');
    } finally { setSaving(false); }
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    setDeleting(true);
    try {
      await client.delete(`/admin/skill-courses/${deleteTarget}`);
      setDeleteTarget(null); fetchData();
    } catch (err) {
      alert(err.response?.data?.error || 'Failed to delete');
    } finally { setDeleting(false); }
  };

  // Category handlers
  const handleAddCategory = async (e) => {
    e.preventDefault(); setCatSaving(true); setCatError('');
    try {
      await client.post('/admin/skill-course-categories', { name: catName });
      setCatName(''); fetchData();
    } catch (err) {
      setCatError(err.response?.data?.error || 'Failed to add category');
    } finally { setCatSaving(false); }
  };

  const handleDeleteCategory = async (id) => {
    try {
      await client.delete(`/admin/skill-course-categories/${id}`);
      fetchData();
    } catch (err) {
      alert(err.response?.data?.error || 'Failed to delete category');
    }
  };

  // Enrollment viewer
  const openEnrollments = async (course) => {
    setEnrollCourse(course); setLoadingEnroll(true);
    try {
      const res = await client.get(`/admin/skill-courses/${course.id}/enrollments`);
      setEnrollments(res.data.enrollments);
    } catch (err) { console.error(err); setEnrollments([]); }
    finally { setLoadingEnroll(false); }
  };

  const closeEnrollments = () => { setEnrollCourse(null); setEnrollments(null); };

  if (loading) return <div className="loading-container"><div className="spinner spinner-lg" /></div>;

  const diffColor = { beginner: 'badge-green', intermediate: 'badge-amber', advanced: 'badge-red' };
  const diffLabel = { beginner: 'Beginner', intermediate: 'Intermediate', advanced: 'Advanced' };

  return (
    <div>
      <div className="page-header">
        <div>
          <h1>Skill Enhancement Courses</h1>
          <p className="page-subtitle">Manage skill courses that students can enroll in</p>
        </div>
        <div style={{ display: 'flex', gap: 'var(--space-3)' }}>
          <button className="btn btn-secondary" onClick={() => setShowCatModal(true)}>
            <HiOutlineTag /> Categories
          </button>
          <button className="btn btn-primary" onClick={openCreate}>
            <HiOutlinePlus /> Add Course
          </button>
        </div>
      </div>

      {/* Filters */}
      <div className="toolbar">
        <div className="filter-group" style={{ display: 'flex', gap: 'var(--space-3)' }}>
          <select className="form-select" value={filterCat} onChange={(e) => setFilterCat(e.target.value)} style={{ width: 'auto' }}>
            <option value="">All Categories</option>
            {categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
          <select className="form-select" value={filterDiff} onChange={(e) => setFilterDiff(e.target.value)} style={{ width: 'auto' }}>
            <option value="">All Levels</option>
            <option value="beginner">Beginner</option>
            <option value="intermediate">Intermediate</option>
            <option value="advanced">Advanced</option>
          </select>
        </div>
      </div>

      {/* Table */}
      <div className="card">
        <div className="data-table-wrapper">
          <table className="data-table">
            <thead>
              <tr>
                <th>Title</th><th>Category</th><th>Difficulty</th><th>Duration</th>
                <th>Provider</th><th>Enrolled</th><th>Status</th><th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {courses.length === 0 ? (
                <tr><td colSpan="8"><div className="empty-state"><HiOutlineLightBulb size={40} style={{ color: 'var(--color-gray-300)', marginBottom: 'var(--space-3)' }} /><p>No skill courses yet. Click "Add Course" to create one.</p></div></td></tr>
              ) : courses.map((c) => (
                <tr key={c.id} style={{ opacity: c.isActive ? 1 : 0.5 }}>
                  <td style={{ fontWeight: 500 }}>
                    {c.title}
                    {c.link && (
                      <a href={c.link} target="_blank" rel="noopener noreferrer"
                        style={{ marginLeft: 'var(--space-2)', fontSize: 'var(--font-xs)', color: 'var(--color-sky-500)' }}>
                        ↗
                      </a>
                    )}
                  </td>
                  <td><span className="badge badge-purple">{c.category?.name}</span></td>
                  <td><span className={`badge ${diffColor[c.difficulty] || 'badge-gray'}`}>{diffLabel[c.difficulty]}</span></td>
                  <td>{c.duration}</td>
                  <td>{c.provider || '—'}</td>
                  <td>
                    <button className="btn btn-ghost btn-sm" onClick={() => openEnrollments(c)}
                      style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                      <HiOutlineEye /> {c._count?.enrollments || 0}
                    </button>
                  </td>
                  <td>
                    <span className={`badge ${c.isActive ? 'badge-green' : 'badge-gray'}`}>
                      {c.isActive ? 'Active' : 'Inactive'}
                    </span>
                  </td>
                  <td className="actions">
                    <button className="btn btn-ghost btn-sm" onClick={() => openEdit(c)} title="Edit"><HiOutlinePencil /></button>
                    <button className="btn btn-ghost btn-sm" onClick={() => setDeleteTarget(c.id)} title="Delete"
                      style={{ color: 'var(--color-danger)' }}><HiOutlineTrash /></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add/Edit Course Modal */}
      {showModal && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()} style={{ maxWidth: 600 }}>
            <div className="modal-header">
              <h2>{editing ? 'Edit Skill Course' : 'Add Skill Course'}</h2>
              <button className="btn btn-ghost" onClick={() => setShowModal(false)}>✕</button>
            </div>
            <form onSubmit={handleSubmit}>
              <div className="modal-body" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
                {error && (
                  <div style={{
                    padding: '10px 14px', borderRadius: '8px',
                    backgroundColor: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626',
                    fontSize: '0.9rem', fontWeight: 500,
                  }}>⚠️ {error}</div>
                )}
                <div className="form-group">
                  <label className="form-label">Title</label>
                  <input className="form-input" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })}
                    required placeholder="e.g. Introduction to Python" />
                </div>
                <div className="form-group">
                  <label className="form-label">Description</label>
                  <textarea className="form-input" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })}
                    required placeholder="Brief description of the course..." rows={3}
                    style={{ resize: 'vertical', fontFamily: 'inherit' }} />
                </div>
                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">Category</label>
                    <select className="form-select" value={form.categoryId} onChange={(e) => setForm({ ...form, categoryId: e.target.value })} required>
                      <option value="">Select Category</option>
                      {categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                  </div>
                  <div className="form-group">
                    <label className="form-label">Difficulty</label>
                    <select className="form-select" value={form.difficulty} onChange={(e) => setForm({ ...form, difficulty: e.target.value })}>
                      <option value="beginner">Beginner</option>
                      <option value="intermediate">Intermediate</option>
                      <option value="advanced">Advanced</option>
                    </select>
                  </div>
                </div>
                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">Duration</label>
                    <input className="form-input" value={form.duration} onChange={(e) => setForm({ ...form, duration: e.target.value })}
                      required placeholder="e.g. 4 weeks" />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Provider (optional)</label>
                    <input className="form-input" value={form.provider} onChange={(e) => setForm({ ...form, provider: e.target.value })}
                      placeholder="e.g. Coursera, Udemy" />
                  </div>
                </div>
                <div className="form-group">
                  <label className="form-label">External Link (optional)</label>
                  <input className="form-input" type="url" value={form.link} onChange={(e) => setForm({ ...form, link: e.target.value })}
                    placeholder="https://..." />
                </div>
              </div>
              <div className="modal-footer">
                <button type="button" className="btn btn-secondary" onClick={() => setShowModal(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary" disabled={saving}>
                  {saving ? 'Saving...' : editing ? 'Update' : 'Create'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Categories Modal */}
      {showCatModal && (
        <div className="modal-overlay" onClick={() => setShowCatModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()} style={{ maxWidth: 440 }}>
            <div className="modal-header">
              <h2>Manage Categories</h2>
              <button className="btn btn-ghost" onClick={() => setShowCatModal(false)}>✕</button>
            </div>
            <div className="modal-body" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
              {catError && (
                <div style={{
                  padding: '10px 14px', borderRadius: '8px',
                  backgroundColor: '#fef2f2', border: '1px solid #fecaca', color: '#dc2626',
                  fontSize: '0.9rem', fontWeight: 500,
                }}>⚠️ {catError}</div>
              )}
              <form onSubmit={handleAddCategory} style={{ display: 'flex', gap: 'var(--space-3)' }}>
                <input className="form-input" value={catName} onChange={(e) => setCatName(e.target.value)}
                  placeholder="New category name" required style={{ flex: 1 }} />
                <button type="submit" className="btn btn-primary" disabled={catSaving}>
                  {catSaving ? '...' : 'Add'}
                </button>
              </form>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2)' }}>
                {categories.length === 0 ? (
                  <p style={{ color: 'var(--color-gray-400)', fontSize: 'var(--font-sm)', textAlign: 'center', padding: 'var(--space-4)' }}>
                    No categories yet
                  </p>
                ) : categories.map((c) => (
                  <div key={c.id} style={{
                    display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                    padding: 'var(--space-3) var(--space-4)',
                    background: 'var(--color-gray-50)', borderRadius: 'var(--radius-md)',
                  }}>
                    <div>
                      <span style={{ fontWeight: 500 }}>{c.name}</span>
                      <span style={{ marginLeft: 'var(--space-2)', fontSize: 'var(--font-xs)', color: 'var(--color-gray-400)' }}>
                        {c._count?.skillCourses || 0} courses
                      </span>
                    </div>
                    <button className="btn btn-ghost btn-sm" onClick={() => handleDeleteCategory(c.id)}
                      style={{ color: 'var(--color-danger)' }} title="Delete category">
                      <HiOutlineTrash />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Enrollment Viewer Modal */}
      {enrollCourse && (
        <div className="modal-overlay" onClick={closeEnrollments}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()} style={{ maxWidth: 600 }}>
            <div className="modal-header">
              <h2>Enrollments — {enrollCourse.title}</h2>
              <button className="btn btn-ghost" onClick={closeEnrollments}>✕</button>
            </div>
            <div className="modal-body">
              {loadingEnroll ? (
                <div style={{ textAlign: 'center', padding: 'var(--space-6)' }}><div className="spinner" /></div>
              ) : enrollments?.length === 0 ? (
                <p style={{ color: 'var(--color-gray-400)', textAlign: 'center', padding: 'var(--space-6)' }}>
                  No students enrolled yet.
                </p>
              ) : (
                <div className="data-table-wrapper">
                  <table className="data-table">
                    <thead><tr><th>Student</th><th>Unique ID</th><th>Batch</th><th>Status</th><th>Enrolled</th></tr></thead>
                    <tbody>
                      {enrollments?.map((e) => (
                        <tr key={e.id}>
                          <td style={{ fontWeight: 500 }}>{e.student?.firstName} {e.student?.lastName}</td>
                          <td><span className="badge badge-sky">{e.student?.enrollmentNo}</span></td>
                          <td>{e.student?.batch?.name} · {e.student?.section?.name}</td>
                          <td>
                            <span className={`badge ${e.status === 'enrolled' ? 'badge-sky' : e.status === 'completed' ? 'badge-green' : 'badge-gray'}`}>
                              {e.status}
                            </span>
                          </td>
                          <td style={{ fontSize: 'var(--font-sm)', color: 'var(--color-gray-500)' }}>
                            {new Date(e.enrolledAt).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      <ConfirmDialog
        open={!!deleteTarget}
        title="Delete Skill Course?"
        message="This will soft-delete the skill course. Existing enrollments will remain in the database."
        onConfirm={handleDelete}
        onCancel={() => setDeleteTarget(null)}
        loading={deleting}
      />
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import client from '../../api/client';
import ConfirmDialog from '../../components/ConfirmDialog';
import { HiOutlinePlus, HiOutlinePencil, HiOutlineTrash, HiOutlineSearch, HiOutlineEye } from 'react-icons/hi';

const DESIGNATION_OPTIONS = ['HOD', 'Professor', 'Assistant Professor', 'Teacher'];

export default function ManageStaff() {
  const [staff, setStaff] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({ employeeId: '', name: '', email: '', password: '', departmentId: '', designation: '', phone: '' });
  const [saving, setSaving] = useState(false);
  const [filterDept, setFilterDept] = useState('');
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [deleting, setDeleting] = useState(false);

  const fetchData = async () => {
    try {
      const [staffRes, deptRes] = await Promise.all([
        client.get('/admin/staff', { params: filterDept ? { departmentId: filterDept } : {} }),
        client.get('/admin/departments'),
      ]);
      setStaff(staffRes.data.staff);
      setDepartments(deptRes.data.departments);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  };

  useEffect(() => { fetchData(); }, [filterDept]);

  const openCreate = () => { setEditing(null); setForm({ employeeId: '', name: '', email: '', password: '', departmentId: '', designation: '', phone: '' }); setShowModal(true); };
  const openEdit = (s) => { setEditing(s); setForm({ employeeId: s.employeeId, name: s.user?.name || '', email: s.user?.email || '', password: '', departmentId: s.departmentId || '', designation: s.designation, phone: s.phone }); setShowModal(true); };

  const handleDesignationChange = (value) => {
    setForm(prev => ({
      ...prev,
      designation: value,
      // Clear departmentId when switching away from HOD
      departmentId: value === 'HOD' ? prev.departmentId : '',
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault(); setSaving(true);
    try {
      const payload = { ...form };
      // Don't send departmentId for non-HOD designations
      if (payload.designation !== 'HOD') {
        delete payload.departmentId;
      }
      if (editing) await client.put(`/admin/staff/${editing.id}`, payload);
      else await client.post('/admin/staff', payload);
      setShowModal(false); fetchData();
    } catch (err) { alert(err.response?.data?.error || err.response?.data?.message || 'Error'); }
    finally { setSaving(false); }
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    setDeleting(true);
    try {
      await client.delete(`/admin/staff/${deleteTarget}`);
      setDeleteTarget(null);
      fetchData();
    } catch (err) {
      alert(err.response?.data?.error || 'Failed to delete staff member');
    } finally {
      setDeleting(false);
    }
  };

  if (loading) return <div className="loading-container"><div className="spinner spinner-lg" /></div>;

  return (
    <div>
      <div className="page-header">
        <div><h1>Staff</h1><p className="page-subtitle">Manage teaching staff</p></div>
        <button className="btn btn-primary" onClick={openCreate}><HiOutlinePlus /> Add Staff</button>
      </div>

      <div className="toolbar">
        <div className="filter-group">
          <select className="form-select" value={filterDept} onChange={(e) => setFilterDept(e.target.value)} style={{ width: 'auto' }}>
            <option value="">All Departments</option>
            {departments.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
          </select>
        </div>
      </div>

      <div className="card">
        <div className="data-table-wrapper">
          <table className="data-table">
            <thead><tr><th>Employee ID</th><th>Name</th><th>Email</th><th>Department</th><th>Designation</th><th>Phone</th><th>Actions</th></tr></thead>
            <tbody>
              {staff.length === 0 ? (
                <tr><td colSpan="7"><div className="empty-state"><p>No staff members yet.</p></div></td></tr>
              ) : staff.map((s) => (
                <tr key={s.id}>
                  <td><span className="badge badge-purple">{s.employeeId}</span></td>
                  <td style={{ fontWeight: 500 }}>{s.user?.name}</td>
                  <td>{s.user?.email}</td>
                  <td>{s.department?.name || '—'}</td>
                  <td>{s.designation}</td>
                  <td>{s.phone}</td>
                  <td className="actions">
                    <Link to={`/admin/staff/${s.id}`} className="btn btn-ghost btn-sm" title="View Profile"><HiOutlineEye /></Link>
                    <button className="btn btn-ghost btn-sm" onClick={() => openEdit(s)}><HiOutlinePencil /></button>
                    <button className="btn btn-ghost btn-sm" onClick={() => setDeleteTarget(s.id)} title="Delete" style={{ color: 'var(--color-danger)' }}><HiOutlineTrash /></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {showModal && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header"><h2>{editing ? 'Edit Staff' : 'Add Staff'}</h2><button className="btn btn-ghost" onClick={() => setShowModal(false)}>✕</button></div>
            <form onSubmit={handleSubmit}>
              <div className="modal-body" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">Employee ID</label>
                    <input className="form-input" value={form.employeeId} onChange={(e) => setForm({ ...form, employeeId: e.target.value })} required disabled={!!editing} placeholder="e.g. EMP001" />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Full Name</label>
                    <input className="form-input" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required placeholder="Full name" />
                  </div>
                </div>
                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">Email</label>
                    <input className="form-input" type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} required placeholder="email@sts.com" />
                  </div>
                  {!editing && (
                    <div className="form-group">
                      <label className="form-label">Password</label>
                      <input className="form-input" type="password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} required placeholder="Set password" />
                    </div>
                  )}
                </div>
                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">Designation</label>
                    <select className="form-select" value={form.designation} onChange={(e) => handleDesignationChange(e.target.value)} required>
                      <option value="">Select Designation</option>
                      {DESIGNATION_OPTIONS.map((d) => <option key={d} value={d}>{d}</option>)}
                    </select>
                  </div>
                  {form.designation === 'HOD' && (
                    <div className="form-group">
                      <label className="form-label">Department</label>
                      <select className="form-select" value={form.departmentId} onChange={(e) => setForm({ ...form, departmentId: e.target.value })} required>
                        <option value="">Select Department</option>
                        {departments.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
                      </select>
                    </div>
                  )}
                </div>
                <div className="form-group">
                  <label className="form-label">Phone</label>
                  <input className="form-input" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} required placeholder="Phone number" />
                </div>
              </div>
              <div className="modal-footer">
                <button type="button" className="btn btn-secondary" onClick={() => setShowModal(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary" disabled={saving}>{saving ? 'Saving...' : editing ? 'Update' : 'Create'}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <ConfirmDialog
        open={!!deleteTarget}
        title="Delete Staff Member?"
        message="This will soft-delete the staff member, remove their class assignments, and deactivate their user account."
        onConfirm={handleDelete}
        onCancel={() => setDeleteTarget(null)}
        loading={deleting}
      />
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import client from '../../api/client';
import ConfirmDialog from '../../components/ConfirmDialog';
import { HiOutlinePlus, HiOutlineEye, HiOutlinePencil, HiOutlineTrash, HiOutlineSearch, HiOutlineX, HiOutlineCamera, HiOutlineHeart } from 'react-icons/hi';

const API_BASE = 'http://localhost:5000';

export default function ManageStudents() {
  const [students, setStudents] = useState([]);
  const [batches, setBatches] = useState([]);
  const [sections, setSections] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [form, setForm] = useState({ enrollmentNo: '', email: '', firstName: '', lastName: '', dob: '', gender: 'male', phone: '', address: '', batchId: '', sectionId: '', semester: '1', photoUrl: '' });
  const [saving, setSaving] = useState(false);
  const [search, setSearch] = useState('');
  const [filterBatch, setFilterBatch] = useState('');
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [previewStudent, setPreviewStudent] = useState(null);
  const [photoPreview, setPhotoPreview] = useState(null);
  const [uploadingPhoto, setUploadingPhoto] = useState(false);
  const fileInputRef = useRef(null);
  const navigate = useNavigate();
  const location = useLocation();
  const basePath = location.pathname.startsWith('/teacher') ? '/teacher' : '/admin';
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [deleting, setDeleting] = useState(false);

  const fetchData = async () => {
    try {
      const params = { page, limit: 15, ...(search && { search }), ...(filterBatch && { batchId: filterBatch }) };
      const isTeacherView = basePath === '/teacher';
      const [studRes, batchRes, secRes] = await Promise.all([
        client.get(`${basePath}/students`, { params }),
        isTeacherView ? { data: { batches: [] } } : client.get('/admin/batches'),
        isTeacherView ? { data: { sections: [] } } : client.get('/admin/sections'),
      ]);
      setStudents(studRes.data.students);
      setTotalPages(studRes.data.totalPages);
      setBatches(batchRes.data.batches);
      setSections(secRes.data.sections);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  };

  useEffect(() => { fetchData(); }, [page, filterBatch]);

  const handleSearch = () => { setPage(1); fetchData(); };

  const openCreate = () => {
    setForm({ enrollmentNo: '', email: '', firstName: '', lastName: '', dob: '', gender: 'male', phone: '', address: '', batchId: batches[0]?.id || '', sectionId: sections[0]?.id || '', semester: '1', photoUrl: '' });
    setPhotoPreview(null);
    setShowModal(true);
  };

  const handlePhotoChange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Show local preview immediately
    const reader = new FileReader();
    reader.onload = (ev) => setPhotoPreview(ev.target.result);
    reader.readAsDataURL(file);

    // Upload to server
    setUploadingPhoto(true);
    try {
      const formData = new FormData();
      formData.append('photo', file);
      const { data } = await client.post('/admin/upload/photo', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      setForm((prev) => ({ ...prev, photoUrl: data.photoUrl }));
    } catch (err) {
      alert('Failed to upload photo. Please try again.');
      setPhotoPreview(null);
    } finally {
      setUploadingPhoto(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault(); setSaving(true);
    try {
      await client.post('/admin/students', form);
      setShowModal(false); fetchData();
    } catch (err) { alert(err.response?.data?.error || err.response?.data?.message || 'Error creating student'); }
    finally { setSaving(false); }
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    setDeleting(true);
    try {
      await client.delete(`/admin/students/${deleteTarget}`);
      setDeleteTarget(null);
      fetchData();
    } catch (err) {
      alert(err.response?.data?.error || 'Failed to delete student');
    } finally {
      setDeleting(false);
    }
  };

  const statusColor = { active: 'badge-green', inactive: 'badge-gray', graduated: 'badge-sky', dropped: 'badge-red' };

  if (loading) return <div className="loading-container"><div className="spinner spinner-lg" /></div>;

  return (
    <div>
      <div className="page-header">
        <div><h1>Students</h1><p className="page-subtitle">{basePath === '/teacher' ? 'View your assigned students' : 'Manage student records'}</p></div>
        {basePath === '/admin' && <button className="btn btn-primary" onClick={openCreate}><HiOutlinePlus /> Add Student</button>}
      </div>

      <div className="toolbar">
        <div className="search-box">
          <HiOutlineSearch className="search-icon" />
          <input className="form-input" placeholder="Search students..."
            value={search} onChange={(e) => setSearch(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSearch()} />
        </div>
        <div className="filter-group">
          <select className="form-select" value={filterBatch} onChange={(e) => { setFilterBatch(e.target.value); setPage(1); }} style={{ width: 'auto' }}>
            <option value="">All Batches</option>
            {batches.map((b) => <option key={b.id} value={b.id}>{b.degree} — {b.name}</option>)}
          </select>
        </div>
      </div>

      <div className="card">
        <div className="data-table-wrapper">
          <table className="data-table">
            <thead><tr><th>Unique ID</th><th>Name</th><th>Batch</th><th>Section</th><th>Semester</th><th>Status</th><th>Actions</th></tr></thead>
            <tbody>
              {students.length === 0 ? (
                <tr><td colSpan="7"><div className="empty-state"><p>No students found.</p></div></td></tr>
              ) : students.map((s) => (
                <tr key={s.id}>
                  <td><span className="badge badge-sky">{s.enrollmentNo}</span></td>
                  <td style={{ fontWeight: 500 }}>{s.firstName} {s.lastName}</td>
                  <td>{s.batch?.degree ? `${s.batch.degree} — ${s.batch.name}` : s.batch?.name}</td>
                  <td>{s.section?.name}</td>
                  <td>Sem {s.semester}</td>
                  <td><span className={`badge ${statusColor[s.status] || 'badge-gray'}`}>{s.status}</span></td>
                  <td className="actions">
                    <button className="btn btn-ghost btn-sm" onClick={() => setPreviewStudent(s)} title="Quick Preview" style={{ color: 'var(--color-purple-500)' }}><HiOutlineEye /></button>
                    <button className="btn btn-ghost btn-sm" onClick={() => navigate(`${basePath}/students/${s.id}`)} title="Full Details"><HiOutlinePencil /></button>
                    {basePath === '/admin' && <button className="btn btn-ghost btn-sm" onClick={() => setDeleteTarget(s.id)} title="Delete" style={{ color: 'var(--color-danger)' }}><HiOutlineTrash /></button>}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {totalPages > 1 && (
          <div className="pagination">
            <button disabled={page <= 1} onClick={() => setPage(page - 1)}>‹</button>
            {Array.from({ length: totalPages }, (_, i) => (
              <button key={i + 1} className={page === i + 1 ? 'active' : ''} onClick={() => setPage(i + 1)}>{i + 1}</button>
            ))}
            <button disabled={page >= totalPages} onClick={() => setPage(page + 1)}>›</button>
          </div>
        )}
      </div>

      {/* ═══ CREATE STUDENT MODAL ═══ */}
      {showModal && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()} style={{ maxWidth: '680px' }}>
            <div className="modal-header"><h2>Add Student</h2><button className="btn btn-ghost" onClick={() => setShowModal(false)}>✕</button></div>
            <form onSubmit={handleSubmit}>
              <div className="modal-body" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
                {/* Photo Upload */}
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-5)', marginBottom: 'var(--space-2)' }}>
                  <div
                    onClick={() => fileInputRef.current?.click()}
                    style={{
                      width: '88px', height: '88px', borderRadius: '50%', overflow: 'hidden',
                      border: '3px dashed var(--color-gray-200)', cursor: 'pointer', flexShrink: 0,
                      display: 'flex', alignItems: 'center', justifyContent: 'center',
                      background: photoPreview ? 'none' : 'var(--color-gray-100)',
                      transition: 'all var(--transition-fast)', position: 'relative',
                    }}
                    onMouseEnter={(e) => e.currentTarget.style.borderColor = 'var(--color-sky-400)'}
                    onMouseLeave={(e) => e.currentTarget.style.borderColor = 'var(--color-gray-200)'}
                  >
                    {photoPreview ? (
                      <img src={photoPreview} alt="Preview" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                    ) : (
                      <div style={{ textAlign: 'center' }}>
                        <HiOutlineCamera size={24} style={{ color: 'var(--color-gray-400)' }} />
                      </div>
                    )}
                    {uploadingPhoto && (
                      <div style={{
                        position: 'absolute', inset: 0, borderRadius: '50%',
                        background: 'rgba(255,255,255,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center',
                      }}>
                        <div className="spinner" />
                      </div>
                    )}
                  </div>
                  <input type="file" ref={fileInputRef} accept="image/jpeg,image/png,image/webp" onChange={handlePhotoChange} style={{ display: 'none' }} />
                  <div>
                    <p style={{ fontSize: 'var(--font-sm)', fontWeight: 600, color: 'var(--color-gray-700)', marginBottom: '4px' }}>Student Photo</p>
                    <p style={{ fontSize: 'var(--font-xs)', color: 'var(--color-gray-400)', lineHeight: 1.4 }}>
                      Click the circle to upload.<br />JPG, PNG, or WebP • Max 5MB
                    </p>
                  </div>
                </div>

                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">Unique ID</label>
                    <input className="form-input" value={form.enrollmentNo} onChange={(e) => setForm({ ...form, enrollmentNo: e.target.value })} required placeholder="e.g. 2024CSE001" />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Email</label>
                    <input className="form-input" type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} required />
                  </div>
                </div>

                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">First Name</label>
                    <input className="form-input" value={form.firstName} onChange={(e) => setForm({ ...form, firstName: e.target.value })} required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Last Name</label>
                    <input className="form-input" value={form.lastName} onChange={(e) => setForm({ ...form, lastName: e.target.value })} required />
                  </div>
                </div>
                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">Date of Birth</label>
                    <input className="form-input" type="date" value={form.dob} onChange={(e) => setForm({ ...form, dob: e.target.value })} required />
                    <span style={{ fontSize: 'var(--font-xs)', color: 'var(--color-gray-400)', marginTop: '4px', display: 'block' }}>Default password will be DOB (DDMMYYYY)</span>
                  </div>
                  <div className="form-group">
                    <label className="form-label">Gender</label>
                    <select className="form-select" value={form.gender} onChange={(e) => setForm({ ...form, gender: e.target.value })}>
                      <option value="male">Male</option>
                      <option value="female">Female</option>
                      <option value="other">Other</option>
                    </select>
                  </div>
                </div>
                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">Phone</label>
                    <input className="form-input" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Semester</label>
                    <input className="form-input" type="number" min="1" max="8" value={form.semester} onChange={(e) => setForm({ ...form, semester: e.target.value })} required />
                  </div>
                </div>
                <div className="form-group">
                  <label className="form-label">Address</label>
                  <input className="form-input" value={form.address} onChange={(e) => setForm({ ...form, address: e.target.value })} required />
                </div>
                <div className="form-row">
                  <div className="form-group">
                    <label className="form-label">Batch</label>
                    <select className="form-select" value={form.batchId} onChange={(e) => setForm({ ...form, batchId: e.target.value })} required>
                      <option value="">Select Batch</option>
                      {batches.map((b) => <option key={b.id} value={b.id}>{b.degree} — {b.name}</option>)}
                    </select>
                  </div>
                  <div className="form-group">
                    <label className="form-label">Section</label>
                    <select className="form-select" value={form.sectionId} onChange={(e) => setForm({ ...form, sectionId: e.target.value })} required>
                      <option value="">Select Section</option>
                      {sections.filter((s) => !form.batchId || s.batchId === form.batchId).map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                  </div>
                </div>
              </div>
              <div className="modal-footer">
                <button type="button" className="btn btn-secondary" onClick={() => setShowModal(false)}>Cancel</button>
                <button type="submit" className="btn btn-primary" disabled={saving || uploadingPhoto}>{saving ? 'Saving...' : 'Create Student'}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ═══ STUDENT PREVIEW MODAL ═══ */}
      {previewStudent && (
        <StudentPreviewModal student={previewStudent} onClose={() => setPreviewStudent(null)} onViewFull={() => { setPreviewStudent(null); navigate(`${basePath}/students/${previewStudent.id}`); }} />
      )}

      <ConfirmDialog
        open={!!deleteTarget}
        title="Delete Student?"
        message="This will soft-delete the student and deactivate their user account. This action can be reversed by an admin."
        onConfirm={handleDelete}
        onCancel={() => setDeleteTarget(null)}
        loading={deleting}
      />
    </div>
  );
}

